impl Order {
    /// `orders.dat` row used by this high-level order.  Only the queue/UI
    /// metadata is read from the row; the simulation still keeps its typed
    /// order state.
    pub fn order_id(&self) -> u8 {
        match self {
            Order::Idle => 0,
            Order::Stop => 1,
            Order::Move { .. } => 6,
            Order::AttackMove { .. } => 13,
            Order::AttackUnit { .. } => 8,
            Order::HoldPosition => 106,
            Order::Patrol { .. } => 151,
            Order::Gather { .. } => 78,
            Order::ReturnCargo { .. } => 85,
            Order::Build { .. } => 15,
            Order::Repair { .. } => 34,
            Order::Construct { .. } => 33,
            Order::Train { .. } => 37,
            Order::Research { .. } => 74,
            Order::Upgrade { .. } => 75,
            Order::Cast { .. } => 80,
            Order::EnterTransport { .. } => 90,
            Order::Unload => 110,
            Order::Burrow => 115,
            Order::Unburrow => 117,
            Order::Siege => 97,
            Order::Unsiege => 98,
            Order::Lift => 73,
            Order::Land { .. } => 70,
            Order::Die => 0,
        }
    }
}

