        let barracks = w.spawn(0, uid::BARRACKS, 320, 320).unwrap();
        let id = w.units[barracks].id;
        w.units[barracks].production.push_back(Order::Train {
            unit_type: uid::MARINE,
        });
        w.units[barracks].production.push_back(Order::Train {
            unit_type: uid::FIREBAT,
        });
