// Translation batch 04.  Only this file is edited by the batch.
//
// The routines below were recovered from the `0x005b3000..=0x005b4fff`
// CUnit/CSprite helper cluster.  Every method name is prefixed with `a04_`
// so the batch cannot collide with the main `SimUnit`/`World` impls or with
// the other concurrent batches.

/// `FUN_005b4d2d`/`0x005b4db0`/`0x005b4e00`: width of the slot field in a
/// packed unit reference when the pool holds at most `0x6a4` (1700, the
/// retail unit-pool size) entries.
const A04_SLOT_BITS_NARROW: u32 = 11;

/// `FUN_005b4d2d`/`0x005b4db0`/`0x005b4e00`: width of the slot field once the
/// pool grows past `0x6a4`; the remaining high bits keep the generation byte
/// (`CUnit+0xa5`).
const A04_SLOT_BITS_WIDE: u32 = 13;

/// `FUN_005b4d2d`/`0x005b4db0`/`0x005b4e00`: the pool size that selects the
/// wide slot field (`0x6a4 < FUN_0060b560()`).
const A04_WIDE_POOL_THRESHOLD: usize = 0x6a4;

impl SimUnit {
    /// `0x005b49a0`: status-modifier count shared by the speed and cooldown
    /// helpers.
    ///
    /// The recovered body is a pure integer combination of three status
    /// sources:
    ///
    /// ```text
    /// base = (CUnit+0x115 != 0)
    /// n    = (CUnit+0xdc & 0x20000000) != 0 ? base + 1 : base
    /// mods = (CUnit+0x116 != 0)            ? n - 1    : n
    /// ```
    ///
    /// `CUnit+0x115` is the Stim Pack timer, `CUnit+0x116` is the Ensnare
    /// timer and `CUnit+0xdc` bit 29 is [`SimUnit::flag_29`].  The
    /// speed/cooldown helpers `FUN_005b4f20`, `FUN_005b5640`, `FUN_005b68b0` and
    /// `FUN_005b6900` spell out the same shape but test bit 28
    /// (`0x10000000`) instead of bit 29, so the two groups are kept separate.
    pub fn a04_status_modifier_count(&self) -> i32 {
        let mut mods = i32::from(self.status.stim_ticks > 0);
        if self.flag_29 {
            mods += 1;
        }
        if self.status.ensnare_ticks > 0 {
            mods -= 1;
        }
        mods
    }

    /// `0x005b3bb0`: wrapper around `FUN_005d48f0(1)`.
    ///
    /// `FUN_005d48f0` only acts when `CUnit+0xdc` bit 6 (Bunker) is set.  It
    /// early-returns when the passed flag is zero or when the unit still has
    /// a `CUnit+0x80` link, then clears the Bunker bit (`FUN_005b6840(0)`) and
    /// the transport bit 5 (`FUN_005b48e0`).  The second `FUN_005b48e0` call
    /// covers the attached subunit at `CUnit+0x70`, which the sim does not
    /// link from the parent; the caller's own two flags are the observable
    /// effect.
    pub fn a04_exit_bunker(&mut self) {
        if !self.in_bunker {
            return;
        }
        // `FUN_005d48f0`: `if (param_1 == 0 || this+0x80 != 0) return;`.
        if self.connected_unit.is_some() {
            return;
        }
        self.in_bunker = false;
        self.in_transport = None;
    }

    /// `0x005b3b57`: the recovered body is a bare `return` (size 1).  Kept as
    /// an explicit hook so callers that dispatch the recovered routine have a
    /// named, testable no-op.
    pub fn a04_empty_body(&self) {}
}

impl World {
    /// `0x005b3620`: the unit's linked target is a Flag Beacon.
    ///
    /// The recovered body first asks `FUN_005b64c0` for the worker flag and, on
    /// success, returns `FUN_005b55d0`: type id below `0xe4`, `units.dat` flag
    /// `0x8` set, a nonzero `CUnit+0xc0` link and a linked target whose type
    /// is `0xd7`.  The fallback branch calls `FUN_005d5c80`, whose only
    /// non-aborting path returns zero, so the predicate above is the whole
    /// result.
    pub fn a04_worker_flag_target(&self, i: usize) -> bool {
        let Some(u) = self.units.get(i) else {
            return false;
        };
        let ty = u.type_id;
        if ty >= 0xe4 || !self.data.unit(ty).is_worker() {
            return false;
        }
        match u.linked_target() {
            Some(id) => self.unit(id).is_some_and(|t| t.type_id == 0xd7),
            None => false,
        }
    }

    /// Slot-field width used by the packed unit-reference helpers
    /// (`FUN_005b4d2d`, `0x005b4db0`, `0x005b4e00`): 11 bits for the classic
    /// 1700-entry pool, 13 bits once the pool grows past `0x6a4`.  The live
    /// `units` vector stands in for `FUN_0060b560`'s pool size.
    pub fn a04_reference_slot_bits(&self) -> u32 {
        if self.units.len() > A04_WIDE_POOL_THRESHOLD {
            A04_SLOT_BITS_WIDE
        } else {
            A04_SLOT_BITS_NARROW
        }
    }

    /// `0x005b4db0`: resolve the 1-based slot stored in the low bits of a
    /// packed unit reference.
    ///
    /// Retail returns `base + (slot - 1) * 0x150`, i.e. the `CUnit*` for a
    /// one-based pool slot, after masking the slot with `(1 << s) - 1`.
    /// `SimUnit` ids are opaque and the pool is a dense vector, so the result
    /// is the id occupying that one-based slot.  A zero reference yields
    /// `None` (retail would index one element before the pool) and an
    /// out-of-range slot yields `None` instead of a stale pointer.
    pub fn a04_unit_id_at_reference(&self, reference: u32) -> Option<u32> {
        if reference == 0 {
            return None;
        }
        let mask = (1u32 << self.a04_reference_slot_bits()) - 1;
        let slot = reference & mask;
        if slot == 0 {
            return None;
        }
        self.units.get(slot as usize - 1).map(|u| u.id)
    }

    /// `0x005b4e00`: pack a one-based slot number and the generation byte
    /// (`CUnit+0xa5`) into the reference used by `0x005b4db0`/`FUN_005b4d2d`.
    ///
    /// Retail derives the slot from the pointer distance to the unit array
    /// (`(ptr - base) / 0x150 + 1`), rejects slots beyond `FUN_0060b560()`,
    /// then returns `(byte@0xa5 << s) | slot`.  `s` is 11 or 13 as selected
    /// by the pool size.  The sim has no per-unit generation byte, so the
    /// caller supplies it; the arithmetic is otherwise unchanged.
    pub fn a04_unit_reference(&self, i: usize, generation: u8) -> u32 {
        if i >= self.units.len() {
            return 0;
        }
        let slot = i as u32 + 1;
        let bits = self.a04_reference_slot_bits();
        (u32::from(generation) << bits) | slot
    }
}

#[cfg(test)]
mod tests_agent04 {
    use super::*;
    use crate::ids::unit as uid;
    use crate::sim::Order;

    fn world() -> World {
        World::new(
            std::sync::Arc::new(crate::data::GameData::bundled().unwrap()),
            crate::map::Terrain::open(64, 64),
            2,
        )
    }

    /// `0x005b49a0`: the modifier count is +1 for Stim, +1 for `CUnit+0xdc`
    /// bit 29 and -1 for Ensnare; the three sources combine additively.
    #[test]
    fn status_modifier_count_combines_stim_ensnare_and_flag29() {
        let mut w = world();
        let u = w.spawn(0, uid::MARINE, 320, 320).unwrap();

        assert_eq!(w.units[u].a04_status_modifier_count(), 0);

        w.units[u].status.stim_ticks = 336;
        assert_eq!(w.units[u].a04_status_modifier_count(), 1);

        w.units[u].status.ensnare_ticks = 75;
        assert_eq!(w.units[u].a04_status_modifier_count(), 0, "both cancel");

        w.units[u].status.stim_ticks = 0;
        assert_eq!(w.units[u].a04_status_modifier_count(), -1);

        // Bit 29 is the second positive source (the units.dat spellcaster
        // flag mirrored into `CUnit+0xdc`).
        w.units[u].flag_29 = true;
        assert_eq!(w.units[u].a04_status_modifier_count(), 0);
        w.units[u].status.ensnare_ticks = 0;
        assert_eq!(w.units[u].a04_status_modifier_count(), 1);
        w.units[u].status.stim_ticks = 336;
        assert_eq!(w.units[u].a04_status_modifier_count(), 2);
        w.units[u].status.ensnare_ticks = 75;
        assert_eq!(w.units[u].a04_status_modifier_count(), 1);
    }

    /// `0x005b3620`: only a worker with a linked Flag Beacon (`0xd7`) passes;
    /// a non-worker with the same link, or a worker without one, fails.
    #[test]
    fn worker_flag_target_requires_a_worker_and_a_flag_beacon() {
        let mut w = world();
        let scv = w.spawn(0, uid::SCV, 320, 320).unwrap();
        let flag = w.spawn(0, 0xd7, 360, 320).unwrap();
        let flag_id = w.units[flag].id;

        assert!(!w.a04_worker_flag_target(scv), "no linked target yet");

        w.units[scv].order = Order::Gather { resource: flag_id };
        assert!(w.a04_worker_flag_target(scv));

        // An ordinary unit carrying the same unit-target order is rejected by
        // the `FUN_005b64c0` worker-flag test.
        let marine = w.spawn(0, uid::MARINE, 320, 360).unwrap();
        w.units[marine].order = Order::AttackUnit { target: flag_id };
        assert!(!w.a04_worker_flag_target(marine));

        // A worker pointing at a non-flag unit is rejected too.
        let depot = w.spawn(0, uid::COMMAND_CENTER, 400, 320).unwrap();
        w.units[scv].order = Order::Repair {
            target: w.units[depot].id,
        };
        assert!(!w.a04_worker_flag_target(scv));

        // Out-of-range indices never panic.
        assert!(!w.a04_worker_flag_target(w.units.len()));
    }

    /// `0x005b3bb0` -> `FUN_005d48f0(1)`: a Bunkered unit drops both links,
    /// but the helper early-returns while a `CUnit+0x80` link is present.
    #[test]
    fn exit_bunker_clears_bunker_and_transport_bits() {
        let mut w = world();
        let bunker = w.spawn(0, uid::BUNKER, 320, 320).unwrap();
        let u = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let bunker_id = w.units[bunker].id;

        w.units[u].in_bunker = true;
        w.units[u].in_transport = Some(bunker_id);
        w.units[u].a04_exit_bunker();
        assert!(!w.units[u].in_bunker);
        assert_eq!(w.units[u].in_transport, None);

        // `FUN_005d48f0` returns early while `CUnit+0x80` is set.
        w.units[u].in_bunker = true;
        w.units[u].in_transport = Some(bunker_id);
        w.units[u].connected_unit = Some(bunker_id);
        w.units[u].a04_exit_bunker();
        assert!(w.units[u].in_bunker);
        assert_eq!(w.units[u].in_transport, Some(bunker_id));

        // A unit that is not in a Bunker is untouched (bit 6 gate).
        w.units[u].in_bunker = false;
        w.units[u].connected_unit = None;
        w.units[u].a04_exit_bunker();
        assert_eq!(w.units[u].in_transport, Some(bunker_id));
    }

    /// `0x005b4e00` / `0x005b4db0`: one-based slots pack into the low field
    /// and resolve back to the same unit; the high generation bits are
    /// ignored by the resolver, as in the retail body.
    #[test]
    fn packed_unit_references_round_trip_through_one_based_slots() {
        let mut w = world();
        let a = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let b = w.spawn(0, uid::MARINE, 340, 320).unwrap();
        let (id_a, id_b) = (w.units[a].id, w.units[b].id);

        assert_eq!(w.a04_reference_slot_bits(), 11);
        assert_eq!(w.a04_unit_reference(a, 0), 1);
        assert_eq!(w.a04_unit_reference(b, 0), 2);
        assert_eq!(w.a04_unit_reference(a, 0x2a), (0x2a << 11) | 1);

        assert_eq!(w.a04_unit_id_at_reference(1), Some(id_a));
        assert_eq!(w.a04_unit_id_at_reference(2), Some(id_b));
        assert_eq!(w.a04_unit_id_at_reference((7 << 11) | 2), Some(id_b));
        assert_eq!(w.a04_unit_id_at_reference(0), None);
        assert_eq!(w.a04_unit_id_at_reference(3), None);
        assert_eq!(w.a04_unit_reference(w.units.len(), 0), 0);

        // Past 0x6a4 entries the slot field widens to 13 bits and the
        // generation byte starts at bit 13.
        let template = w.units[a].clone();
        while w.units.len() <= A04_WIDE_POOL_THRESHOLD {
            w.units.push(template.clone());
        }
        assert_eq!(w.a04_reference_slot_bits(), 13);
        assert_eq!(w.a04_unit_reference(0, 1), (1 << 13) | 1);
        assert_eq!(w.a04_unit_id_at_reference((3 << 13) | 1), Some(id_a));
    }

    /// `0x005b3b57`: the recovered routine is empty, so calling it leaves the
    /// unit untouched.
    #[test]
    fn empty_body_changes_nothing() {
        let mut w = world();
        let u = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        w.units[u].hp = 1234;
        w.units[u].order = Order::HoldPosition;
        let before = format!("{:?}", w.units[u]);
        w.units[u].a04_empty_body();
        assert_eq!(before, format!("{:?}", w.units[u]));
    }
}

// ===========================================================================
// Merged from src/translated/agent06.rs
// ===========================================================================
// Translation batch 06.  Only this file is edited by the batch.
//
// The ledger rows recovered for `0x005b7000..=0x005b9fff` are the order-list
// helpers of `CUnit`.  The list head is `CUnit+0x74` (the current order), the
// tail is `CUnit+0x78`, and `CUnit+0x84` is the order-count byte.  The typed
// model splits that list into [`SimUnit::order`] (head) and
// [`SimUnit::queue`] (the remaining nodes), so a node's `+8` order-type byte
// is `Order::order_id()` and the `DAT_00f8ad50[type]` lookup is the
// `orders.dat` highlight column.

/// `DAT_00f8ad50`: `orders.dat` highlight column.  Every order-list helper
/// tests `highlight != -1` before touching `CUnit+0x84`; rows without a
/// highlight are linked but do not consume a queue slot.
fn a06_uses_queue_slot(data: &GameData, order: &Order) -> bool {
    data.order(order.order_id())
        .is_some_and(|row| row.highlight != -1)
}

/// Number of nodes in the retail order list: the current order plus queued
/// orders.  `Order::Idle` is the typed model's empty-list sentinel, not a
/// linked node.
fn a06_order_list_len(unit: &SimUnit) -> usize {
    usize::from(!matches!(unit.order, Order::Idle)) + unit.queue.len()
}

/// One current order plus the eight pending slots (`CUnit+0x84 < 9` in
/// `0x005b7520`, matching [`crate::sim::MAX_ORDER_QUEUE`]).
const A06_ORDER_LIST_CAPACITY: usize = crate::sim::MAX_ORDER_QUEUE + 1;

impl SimUnit {
    /// `0x005b7140`: unlink every order node from the list at `CUnit+0x74`.
    /// For each node whose `DAT_00f8ad50[type]` entry is not `-1` the
    /// `CUnit+0x84` byte is decremented (clamped at zero), then the node is
    /// removed with `FUN_00577210`/`FUN_005772d0`.
    ///
    /// The typed model derives the count byte from the list, so clearing the
    /// current order and the queue is equivalent.  Returns the number of
    /// slot-consuming nodes removed.  `order_row` is the Rust cache of the
    /// head node's order id and is cleared with the list.
    pub fn a06_clear_order_list(&mut self, data: &GameData) -> u16 {
        let mut removed = 0u16;
        if !matches!(self.order, Order::Idle) && a06_uses_queue_slot(data, &self.order) {
            removed += 1;
        }
        for order in &self.queue {
            if a06_uses_queue_slot(data, order) {
                removed += 1;
            }
        }
        self.order = Order::Idle;
        self.order_row = 0;
        self.queue.clear();
        removed
    }

    /// `0x005b7c20`: unlink the head node (`CUnit+0x74`, the current order)
    /// and decrement `CUnit+0x84` when that order's highlight is not `-1`.
    /// The next queued node becomes the new head.  The retail helper assumes
    /// a non-empty list; the typed version reports an empty list as `None`.
    ///
    /// Returns the removed order and whether it consumed a queue slot.
    pub fn a06_pop_order_head(&mut self, data: &GameData) -> Option<(Order, bool)> {
        if matches!(self.order, Order::Idle) {
            return None;
        }
        let removed = std::mem::replace(&mut self.order, Order::Idle);
        let used_slot = a06_uses_queue_slot(data, &removed);
        if let Some(next) = self.queue.pop_front() {
            self.order = next;
        }
        self.order_row = self.order.order_id();
        Some((removed, used_slot))
    }

    /// `0x005b7410`: unlink the order node passed in `param_1`, decrementing
    /// `CUnit+0x84` when its `DAT_00f8ad50[type]` entry is not `-1`.  The
    /// caller guarantees a linked node; the typed equivalent searches the
    /// current order first and then the queue.
    ///
    /// Returns `Some(used_slot)` when an equal order was unlinked, or `None`
    /// when it was not in the list.  Removing the current node promotes the
    /// next queued order, matching the head-pointer update performed by
    /// `FUN_00577210`.
    pub fn a06_remove_order_node(&mut self, target: &Order, data: &GameData) -> Option<bool> {
        if matches!(target, Order::Idle) {
            return None;
        }
        if &self.order == target {
            let used_slot = a06_uses_queue_slot(data, target);
            self.order = self.queue.pop_front().unwrap_or(Order::Idle);
            self.order_row = self.order.order_id();
            return Some(used_slot);
        }
        let pos = self.queue.iter().position(|order| order == target)?;
        let removed = self.queue.remove(pos)?;
        Some(a06_uses_queue_slot(data, &removed))
    }

    /// `0x005b7520`: allocate a node for `order` and insert it at the head
    /// of the list, making it the current order.  `CUnit+0x84` is incremented
    /// only for rows whose highlight is not `-1`.  Allocation failure takes
    /// the retail error path; the typed queue cannot fail to allocate.
    ///
    /// The decompiled guard also accepts every insertion when `CUnit+0x134`
    /// is null.  That field is not modelled, so this translation enforces the
    /// `count < 9` arm ([`A06_ORDER_LIST_CAPACITY`]).  Returns whether the
    /// inserted row consumes a queue slot, or [`SimError::QueueFull`] when
    /// the head insert would exceed nine nodes.
    pub fn a06_insert_order_at_head(
        &mut self,
        order: Order,
        data: &GameData,
    ) -> Result<bool, SimError> {
        if matches!(order, Order::Idle) {
            return Ok(false);
        }
        if a06_order_list_len(self) >= A06_ORDER_LIST_CAPACITY {
            return Err(SimError::QueueFull);
        }
        let used_slot = a06_uses_queue_slot(data, &order);
        let old = std::mem::replace(&mut self.order, order);
        if !matches!(old, Order::Idle) {
            self.queue.push_front(old);
        }
        self.order_row = self.order.order_id();
        Ok(used_slot)
    }

    /// `0x005b7460`: wrapper around `0x005b7520` that supplies the fixed
    /// serialized tag `0xe4` and forwards the caller's list anchor.  The
    /// typed order has no raw tag/anchor, so this is the same head insertion
    /// with its capacity and slot accounting unchanged.
    pub fn a06_insert_order_head_default(
        &mut self,
        order: Order,
        data: &GameData,
    ) -> Result<bool, SimError> {
        self.a06_insert_order_at_head(order, data)
    }

    /// `0x005b71f0`: issue `order` at the list head.  When the list is empty
    /// the decompiled path uses `FUN_005b6cd0` (list initialisation); when it
    /// is non-empty it uses `0x005b7520` (head insertion).  Both make the new
    /// order the head, so an idle unit starts the order directly and a busy
    /// unit defers to [`Self::a06_insert_order_at_head`].
    pub fn a06_issue_order_or_start(
        &mut self,
        order: Order,
        data: &GameData,
    ) -> Result<bool, SimError> {
        if a06_order_list_len(self) == 0 {
            if matches!(order, Order::Idle) {
                return Ok(false);
            }
            let used_slot = a06_uses_queue_slot(data, &order);
            self.order = order;
            self.order_row = self.order.order_id();
            Ok(used_slot)
        } else {
            self.a06_insert_order_at_head(order, data)
        }
    }
}

impl World {
    /// `0x005b76a0`: reject a non-null second argument, then forward
    /// `(order, 0, 0, 0xe4, flag)` to `FUN_005b76f0`.  In the typed model the
    /// absent argument is `target: None, pos: None`; the row goes through the
    /// recovered dispatcher.  The final `FUN_005b76f0` flag selects which
    /// queued orders are trimmed before issuing and has no separate typed
    /// state of its own.
    pub fn a06_issue_order_without_argument(
        &mut self,
        unit_id: u32,
        order_id: u8,
    ) -> Result<(), SimError> {
        self.issue_order_id(unit_id, order_id, None, None)
    }

    /// `0x005b7b90`: forward an order row, its target and its position to
    /// `FUN_005b76f0` with the fixed tag byte `0xe4`.
    pub fn a06_issue_order_row(
        &mut self,
        unit_id: u32,
        order_id: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        self.issue_order_id(unit_id, order_id, target, pos)
    }

    /// `0x005b7d40`: set bit 0 of `CUnit+0x93`, issue the row through
    /// `FUN_005b76f0` with the position and the queue flag set, then call
    /// `FUN_005b8090`.  The `FUN_005b8090` decompilation failed, so only the
    /// recovered flag write and order dispatch are modelled here.
    pub fn a06_issue_order_set_flags_93_bit0(
        &mut self,
        unit_id: u32,
        order_id: u8,
        pos: Option<(i32, i32)>,
    ) -> Result<(), SimError> {
        let i = self.index_of(unit_id).ok_or(SimError::BadUnit)?;
        self.units[i].flags_93 |= 1;
        self.issue_order_id(unit_id, order_id, None, pos)
    }

    /// `0x005b7e60`: command-card dispatcher.  The selector chooses which
    /// caller fields become the serialized position and target:
    ///
    /// * `0`: position `(0, 0)`, no target.
    /// * `1`: delegate to `FUN_005b7dd0`, which rejects a non-null second
    ///   argument and issues with no arguments.
    /// * `2`, `3`: the caller position, no target (they differ only in the
    ///   `0xe4` tag byte, which has no typed equivalent).
    /// * `4`: the caller position and target.
    ///
    /// Every recognized case sets `CUnit+0x93` bit 0 before `FUN_005b76f0`
    /// and then calls `FUN_005b8090` (not decompiled).  Returns `false` for an
    /// unknown selector, which the decompiled default path returns from
    /// without changing the unit.
    pub fn a06_issue_order_variant(
        &mut self,
        unit_id: u32,
        variant: u8,
        order_id: u8,
        target: Option<u32>,
        pos: Option<(i32, i32)>,
    ) -> Result<bool, SimError> {
        let (target, pos) = match variant {
            0 => (None, Some((0, 0))),
            1 => {
                if target.is_some() {
                    // `FUN_0058b640` is the retail fatal path for a non-null
                    // second argument; the typed wrapper reports it instead.
                    return Err(SimError::InvalidTarget);
                }
                (None, None)
            }
            2 | 3 => (None, pos),
            4 => (target, pos),
            _ => return Ok(false),
        };
        let i = self.index_of(unit_id).ok_or(SimError::BadUnit)?;
        self.units[i].flags_93 |= 1;
        self.issue_order_id(unit_id, order_id, target, pos)?;
        Ok(true)
    }
}

#[cfg(test)]
mod tests_agent06 {
    use super::*;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn a06_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn a06_marine(world: &mut World) -> u32 {
        let index = world.spawn(0, uid::MARINE, 320, 320).unwrap();
        world.units[index].id
    }

    #[test]
    fn a06_clear_order_list_removes_current_and_queued_orders() {
        let mut world = a06_world();
        let data = world.data.clone();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();
        world.issue(id, Order::Move { pos: (400, 400) }).unwrap();
        world.queue_order(id, Order::Stop).unwrap();
        // A row with highlight -1 is linked but does not consume a slot.
        assert_eq!(data.order(106).unwrap().highlight, -1);
        world.units[index].queue.push_back(Order::HoldPosition);

        let removed = world.units[index].a06_clear_order_list(data.as_ref());
        assert_eq!(removed, 2, "Move and Stop consume slots, Hold does not");
        assert_eq!(world.units[index].order, Order::Idle);
        assert_eq!(world.units[index].order_row, 0);
        assert!(world.units[index].queue.is_empty());
    }

    #[test]
    fn a06_pop_order_head_promotes_the_next_queued_order() {
        let mut world = a06_world();
        let data = world.data.clone();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();
        let first = Order::Move { pos: (400, 400) };
        world.issue(id, first.clone()).unwrap();
        world.queue_order(id, Order::Stop).unwrap();
        world.units[index].queue.push_back(Order::HoldPosition);

        let (removed, used_slot) = world.units[index]
            .a06_pop_order_head(data.as_ref())
            .expect("head node");
        assert_eq!(removed, first);
        assert!(used_slot);
        assert_eq!(world.units[index].order, Order::Stop);
        assert_eq!(world.units[index].order_row, 1);

        let (removed, used_slot) = world.units[index]
            .a06_pop_order_head(data.as_ref())
            .expect("Stop node");
        assert_eq!(removed, Order::Stop);
        assert!(used_slot);
        assert_eq!(world.units[index].order, Order::HoldPosition);
        assert_eq!(world.units[index].order_row, 106);

        let (removed, used_slot) = world.units[index]
            .a06_pop_order_head(data.as_ref())
            .expect("Hold node");
        assert_eq!(removed, Order::HoldPosition);
        assert!(!used_slot, "row 106 has highlight -1");
        assert_eq!(world.units[index].order, Order::Idle);
        assert_eq!(world.units[index].order_row, 0);

        assert!(
            world.units[index]
                .a06_pop_order_head(data.as_ref())
                .is_none()
        );
    }

    #[test]
    fn a06_remove_order_node_handles_queued_current_and_missing_nodes() {
        let mut world = a06_world();
        let data = world.data.clone();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();
        let current = Order::Move { pos: (400, 400) };
        let queued = Order::Move { pos: (500, 500) };
        world.issue(id, current.clone()).unwrap();
        world.queue_order(id, Order::Stop).unwrap();
        world.units[index].queue.push_back(queued.clone());
        world.units[index].queue.push_back(Order::HoldPosition);

        assert_eq!(
            world.units[index].a06_remove_order_node(&Order::Stop, data.as_ref()),
            Some(true),
            "row 1 consumes a slot"
        );
        assert_eq!(
            world.units[index].a06_remove_order_node(&Order::HoldPosition, data.as_ref()),
            Some(false),
            "row 106 is linked without a slot"
        );
        assert_eq!(
            world.units[index].a06_remove_order_node(&current, data.as_ref()),
            Some(true)
        );
        assert_eq!(
            world.units[index].order, queued,
            "removing the head promotes its successor"
        );
        assert_eq!(
            world.units[index].a06_remove_order_node(&Order::Stop, data.as_ref()),
            None
        );
        assert_eq!(world.units[index].order_row, 6);
    }

    #[test]
    fn a06_insert_order_at_head_caps_the_list_at_nine_nodes() {
        let mut world = a06_world();
        let data = world.data.clone();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();

        for i in 0..A06_ORDER_LIST_CAPACITY {
            let used_slot = world.units[index]
                .a06_insert_order_at_head(
                    Order::Move {
                        pos: (400 + i as i32, 400),
                    },
                    data.as_ref(),
                )
                .unwrap();
            assert!(used_slot, "Move row 6 consumes a slot");
        }
        assert_eq!(world.units[index].queue.len(), 8);
        assert_eq!(world.units[index].order, Order::Move { pos: (408, 400) });
        let full = world.units[index]
            .a06_insert_order_at_head(Order::Move { pos: (900, 900) }, data.as_ref());
        assert_eq!(full, Err(SimError::QueueFull));
        assert_eq!(world.units[index].queue.len(), 8);

        let other = a06_marine(&mut world);
        let other_index = world.index_of(other).unwrap();
        let used_slot = world.units[other_index]
            .a06_insert_order_at_head(Order::HoldPosition, data.as_ref())
            .unwrap();
        assert!(!used_slot, "row 106 does not consume a slot");
        assert_eq!(world.units[other_index].order, Order::HoldPosition);
    }

    #[test]
    fn a06_insert_order_head_default_matches_the_delegated_wrapper() {
        let mut world = a06_world();
        let data = world.data.clone();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();

        assert_eq!(
            world.units[index].a06_insert_order_head_default(Order::Stop, data.as_ref()),
            Ok(true)
        );
        assert_eq!(world.units[index].order, Order::Stop);
        assert_eq!(world.units[index].order_row, 1);

        assert_eq!(
            world.units[index]
                .a06_insert_order_head_default(Order::Move { pos: (400, 400) }, data.as_ref()),
            Ok(true)
        );
        assert_eq!(world.units[index].order, Order::Move { pos: (400, 400) });
        assert_eq!(world.units[index].queue.len(), 1);
        assert_eq!(world.units[index].queue.front(), Some(&Order::Stop));
    }

    #[test]
    fn a06_issue_order_or_start_uses_the_empty_list_path_then_queues() {
        let mut world = a06_world();
        let data = world.data.clone();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();

        assert_eq!(
            world.units[index]
                .a06_issue_order_or_start(Order::Move { pos: (400, 400) }, data.as_ref()),
            Ok(true)
        );
        assert_eq!(world.units[index].order, Order::Move { pos: (400, 400) });
        assert!(world.units[index].queue.is_empty());
        assert_eq!(world.units[index].order_row, 6);

        assert_eq!(
            world.units[index].a06_issue_order_or_start(Order::Stop, data.as_ref()),
            Ok(true)
        );
        assert_eq!(world.units[index].order, Order::Stop);
        assert_eq!(
            world.units[index].queue.front(),
            Some(&Order::Move { pos: (400, 400) })
        );
        assert_eq!(world.units[index].order_row, 1);
    }

    #[test]
    fn a06_issue_order_without_argument_dispatches_the_recovered_row() {
        let mut world = a06_world();
        let id = a06_marine(&mut world);
        world.a06_issue_order_without_argument(id, 106).unwrap();
        let index = world.index_of(id).unwrap();
        assert_eq!(world.units[index].order, Order::HoldPosition);
        assert_eq!(world.units[index].order_row, 106);

        assert_eq!(
            world.a06_issue_order_without_argument(9999, 106),
            Err(SimError::BadUnit)
        );
    }

    #[test]
    fn a06_issue_order_row_forwards_target_and_position() {
        let mut world = a06_world();
        let id = a06_marine(&mut world);
        world
            .a06_issue_order_row(id, 6, None, Some((400, 400)))
            .unwrap();
        let index = world.index_of(id).unwrap();
        assert_eq!(world.units[index].order, Order::Move { pos: (400, 400) });
        assert_eq!(world.units[index].order_row, 6);

        assert_eq!(
            world.a06_issue_order_row(9999, 6, None, Some((400, 400))),
            Err(SimError::BadUnit)
        );
    }

    #[test]
    fn a06_issue_order_set_flags_93_bit0_sets_the_flag_before_dispatch() {
        let mut world = a06_world();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();
        world.units[index].flags_93 = 0;

        world
            .a06_issue_order_set_flags_93_bit0(id, 6, Some((400, 400)))
            .unwrap();
        assert_eq!(world.units[index].flags_93 & 1, 1);
        assert_eq!(world.units[index].order, Order::Move { pos: (400, 400) });
        assert_eq!(world.units[index].order_row, 6);

        assert_eq!(
            world.a06_issue_order_set_flags_93_bit0(9999, 6, None),
            Err(SimError::BadUnit)
        );
    }

    #[test]
    fn a06_issue_order_variant_selects_the_recovered_argument_shape() {
        let mut world = a06_world();
        let id = a06_marine(&mut world);
        let index = world.index_of(id).unwrap();

        assert_eq!(
            world.a06_issue_order_variant(id, 9, 6, None, Some((400, 400))),
            Ok(false),
            "the default selector returns without issuing"
        );
        assert_eq!(world.units[index].order, Order::Idle);

        assert_eq!(
            world.a06_issue_order_variant(id, 0, 106, None, Some((900, 900))),
            Ok(true),
            "selector 0 issues the row with a zero position"
        );
        assert_eq!(world.units[index].flags_93 & 1, 1);
        assert_eq!(world.units[index].order, Order::HoldPosition);

        let other = a06_marine(&mut world);
        assert_eq!(
            world.a06_issue_order_variant(other, 1, 106, Some(123), None),
            Err(SimError::InvalidTarget),
            "selector 1 rejects a second argument"
        );
        let other_index = world.index_of(other).unwrap();
        assert_eq!(world.units[other_index].order, Order::Idle);
        assert_eq!(world.units[other_index].flags_93 & 1, 0);

        let third = a06_marine(&mut world);
        assert_eq!(
            world.a06_issue_order_variant(third, 4, 6, None, Some((400, 400))),
            Ok(true)
        );
        let third_index = world.index_of(third).unwrap();
        assert_eq!(
            world.units[third_index].order,
            Order::Move { pos: (400, 400) }
        );
        assert_eq!(world.units[third_index].flags_93 & 1, 1);
    }
}

// ===========================================================================
// Merged from src/translated/agent08.rs
// ===========================================================================
// Translation batch 08.  Only this file is edited by the batch.
//
// Ten `decompiled_uncited` routines from the `0x005c0000..=0x005c7fff`
// client helper region (trigger/ability and unit-order predicates).  Every
// item below names the exact retail address it was recovered from.
//
// The recovered code expresses several failures with the non-returning
// assertion helpers `FUN_005b4cd0` / `FUN_0058b640`.  Those paths are
// reported as `Result::Err(())` instead of aborting the host process, so
// the observable predicate remains testable without killing the test
// runner.

impl SimUnit {
    /// `0x005c4da0`: true when `CUnit+0x4d` (the one-byte `orders.dat` row
    /// id) is `0x6a` and `CUnit+0x4e` (the order state byte) is zero.
    ///
    /// `0x6a` is orders.dat row 106, Hold Position (`Order::order_id`
    /// returns 106 for [`Order::HoldPosition`]).  The Rust order model has
    /// no separate hold sub-state, so the state-zero branch is the plain
    /// hold order.
    pub fn a08_is_hold_position_idle(&self) -> bool {
        matches!(self.order, Order::HoldPosition)
    }

    /// `0x005c7331`: the 16-bit selector in `AX` matches this unit when
    /// `AX == 0x22` (orders.dat row 34, Place Add-On) or when the unit's
    /// `CUnit+0x4d` order byte lies in `0x7b..=0x81` (Nuke Train through
    /// Initializing Arbiter, rows 123..=129).
    pub fn a08_order_matches_addon_or_nuke(&self, selector: u16) -> bool {
        a08_order_code_matches_addon_or_nuke(selector, self.order.order_id())
    }
}

impl World {
    /// `0x005c2350`: tail of the Shield Battery recharge step whose main
    /// body is `FUN_005c2210`.
    ///
    /// `recharged_id` is the unit carrying the recharge order (`CUnit+0x60`
    /// shields, `CUnit+0x4e` order state); `battery_id` is the Shield
    /// Battery it points back to (`CUnit+0xa2` fixed-point energy).  Retail
    /// stops when the recharged pool reached `units.dat` maximum shields
    /// (`max << 8`) or the battery has no energy left.  On that path it
    /// clears the battery's `CUnit+0x5c` back-link when it still names the
    /// recharged unit and returns to the order dispatcher.
    ///
    /// Returns true when the pair finished (the retail non-tail path) and
    /// the back-link is now clear.
    pub fn a08_shield_battery_finish_tick(&mut self, recharged_id: u32, battery_id: u32) -> bool {
        let (Some(recharged), Some(battery)) =
            (self.index_of(recharged_id), self.index_of(battery_id))
        else {
            return false;
        };
        let max_shields = fp(self.data.unit(self.units[recharged].type_id).shield_points as i32);
        let pool_full = self.units[recharged].shields >= max_shields;
        let battery_empty = self.units[battery].energy_fixed() <= 0;
        if !(pool_full || battery_empty) {
            return false;
        }
        // `0x005c2350`: clear the back-link only when it still names the
        // recharged unit (`CUnit+0x5c == ESI`).
        if self.units[battery].target == Some(recharged_id) {
            self.units[battery].target = None;
        }
        true
    }

    /// `0x005c4dc0`: validation gate for a unit type's `units.dat` flag
    /// `0x80000`.  Retail reads the flag word through `DAT_00f8fa08`; a
    /// type without the flag is accepted (`Ok(true)`).
    ///
    /// With the flag set, retail walks the unit list (`DAT_00fa3724`) for
    /// any unit whose `CUnit+0x4c` owner equals the argument and asserts
    /// (`FUN_0058b640`) when one exists; this translation reports that as
    /// `Err(())`.  With no such owner it reports `Ok(false)`.
    pub fn a08_unit_type_owner_query(&self, type_id: u16, owner: u8) -> Result<bool, ()> {
        let Some(ty) = self.data.units.get(type_id as usize) else {
            return Ok(false);
        };
        if ty.flags & 0x0008_0000 == 0 {
            return Ok(true);
        }
        if self.units.iter().any(|u| u.owner == owner) {
            Err(())
        } else {
            Ok(false)
        }
    }

    /// `0x005c5f9a`: column counterpart of
    /// [`Self::a08_placement_tile_row_matches`].  Both coordinates are
    /// converted with the recovered pixel-to-tile expression
    /// `(v + ((v >> 31) & 31)) >> 5` (see [`a08_tile_index`]); the unit-side
    /// coordinate first subtracts the type's `units.dat` placement X
    /// (`DAT_00f90cb8`, stride 4).
    ///
    /// Retail returns zero when the two columns differ and calls the
    /// assertion `FUN_005b4cd0` when they coincide.  Coincidence is
    /// therefore `Err(())` here.
    pub fn a08_placement_columns_differ(
        &self,
        point_x: i32,
        unit_x: i32,
        type_id: u16,
    ) -> Result<(), ()> {
        let Some(ty) = self.data.units.get(type_id as usize) else {
            return Ok(());
        };
        let offset = ty.placement.x as i32;
        if a08_tile_index(point_x) == a08_tile_index(unit_x.wrapping_sub(offset)) {
            Err(())
        } else {
            Ok(())
        }
    }

    /// `0x005c5fcd`: true when the caller's Y coordinate and a unit-side Y
    /// coordinate, after subtracting the type's `units.dat` placement Y
    /// (`DAT_00f90cba`, stride 4), land on the same 32-pixel row.  This is
    /// the same signed rounding as `0x005c5f9a`; the routine returns 1 for
    /// a match and 0 otherwise.
    pub fn a08_placement_tile_row_matches(&self, point_y: i32, unit_y: i32, type_id: u16) -> bool {
        let Some(ty) = self.data.units.get(type_id as usize) else {
            return false;
        };
        let offset = ty.placement.y as i32;
        a08_tile_index(point_y) == a08_tile_index(unit_y.wrapping_sub(offset))
    }
}

/// `0x005c5060`: write bit 7 of the byte at `object+0xe` from the
/// parameter, preserving bits 0..=6 (`v = (v & 0x7f) | (param << 7)`).
/// The client keeps this flag on its sprite/iScript object; the helper is
/// kept as a pure byte operation because that object is not part of the
/// simulation world.
pub fn a08_set_sprite_flag_high_bit(flags: u8, set: bool) -> u8 {
    (flags & 0x7f) | ((set as u8) << 7)
}

/// `0x005c6329`: choose an entry from the first non-empty group of the six
/// 16-entry arrays based at `&DAT_00fa3740`.
///
/// `counts` is the parallel `DAT_00fa38c0` count array and `rng` is the
/// value returned by the retail RNG helper `FUN_0073f3b0(0x13)`.  A group
/// with count one returns slot zero; otherwise the slot is `rng % count`.
/// Retail returns the stored value at that slot, so the translation returns
/// `(group, slot)` for the caller's parallel value rows.  `None` means
/// every one of the six counts was zero (the retail loop then returns the
/// last zero count).
pub fn a08_first_nonempty_group_pick(counts: &[u32; 6], rng: u32) -> Option<(usize, u32)> {
    for (group, &count) in counts.iter().enumerate() {
        if count == 0 {
            continue;
        }
        let slot = if count == 1 { 0 } else { rng % count };
        return Some((group, slot));
    }
    None
}

/// `0x005c65d0`: scan a candidate row and keep the strictly smallest cost
/// (retail calls the distance helper `FUN_00604060` for each candidate).
/// The comparison is `<`, so an equal later cost does not replace the
/// earlier one.  Retail returns the candidate array element; the index into
/// the caller's parallel cost row is returned here so the caller keeps
/// ownership of the values.
pub fn a08_cheapest_candidate(costs: &[u32]) -> Option<usize> {
    let mut best: Option<(u32, usize)> = None;
    for (index, &cost) in costs.iter().enumerate() {
        if best.is_none_or(|(previous, _)| cost < previous) {
            best = Some((cost, index));
        }
    }
    best.map(|(_, index)| index)
}

/// `0x005c7331` body: `AX` is 0x22 (orders.dat row 34, Place Add-On) or the
/// unit's `CUnit+0x4d` order id is in `0x7b..=0x81` (rows 123..=129, Nuke
/// Train through Initializing Arbiter).  The unit byte is passed raw so
/// callers can feed a recovered order id that has no typed [`Order`] row.
pub fn a08_order_code_matches_addon_or_nuke(selector: u16, order_id: u8) -> bool {
    selector == 0x22 || (0x7b..=0x81).contains(&order_id)
}

/// `0x005c740a`: the 16-bit selector is one of `0x7c`, `0x7d`, `0x90` or
/// `0xa2` (orders.dat rows Nuke Launch 124, Nuke Paint 125, cConsume 144
/// and Computer Return 162).  Every other value returns zero.
pub fn a08_is_nuke_or_special_row(selector: u16) -> bool {
    matches!(selector, 0x7c | 0x7d | 0x90 | 0xa2)
}

/// The signed 32-pixel row/column index used by `0x005c5f9a` and
/// `0x005c5fcd`.  Retail emits `(v + ((v >> 31) & 31)) >> 5`: for
/// non-negative pixels that is a plain floor division by 32, while a
/// negative pixel adds 31 first, so `-1..=-31` map to tile 0 and `-32`
/// maps to tile -1.  This is the retail conversion, not Euclidean division.
fn a08_tile_index(v: i32) -> i32 {
    v.wrapping_add((v >> 31) & 31) >> 5
}

#[cfg(test)]
mod tests_agent08 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn test_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    #[test]
    fn a08_hold_position_predicate_reads_the_order() {
        // `0x005c4da0`: order byte 0x6a with state zero.
        let mut w = test_world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        assert!(!w.units[marine].a08_is_hold_position_idle());
        w.issue(w.units[marine].id, Order::HoldPosition).unwrap();
        assert!(w.units[marine].a08_is_hold_position_idle());
        w.issue(w.units[marine].id, Order::Stop).unwrap();
        assert!(!w.units[marine].a08_is_hold_position_idle());
    }

    #[test]
    fn a08_shield_battery_tail_clears_the_back_link() {
        // `0x005c2350`: stop at a full pool or an empty battery.
        let mut w = test_world();
        let battery = w.spawn(0, uid::SHIELD_BATTERY, 320, 320).unwrap();
        let target = w.spawn(0, uid::ZEALOT, 340, 320).unwrap();
        let battery_id = w.units[battery].id;
        let target_id = w.units[target].id;
        let max = fp(w.data.unit(uid::ZEALOT).shield_points as i32);

        // Full pool, back-link set: finished, link cleared.
        w.units[target].shields = max;
        w.units[battery].target = Some(target_id);
        assert!(w.a08_shield_battery_finish_tick(target_id, battery_id));
        assert_eq!(w.units[battery].target, None);

        // Partial pool but an empty battery also finishes the pair.
        w.units[target].shields = max / 2;
        w.units[battery].set_energy_fixed(0);
        w.units[battery].target = Some(target_id);
        assert!(w.a08_shield_battery_finish_tick(target_id, battery_id));
        assert_eq!(w.units[battery].target, None);

        // Partial pool and energy left: the recharge continues, link stays.
        w.units[target].shields = max / 2;
        w.units[battery].set_energy_points(50);
        w.units[battery].target = Some(target_id);
        assert!(!w.a08_shield_battery_finish_tick(target_id, battery_id));
        assert_eq!(w.units[battery].target, Some(target_id));
    }

    #[test]
    fn a08_unit_type_owner_gate_follows_units_dat_flag_80000() {
        // `0x005c4dc0`.
        let mut w = test_world();
        let with_flag = w
            .data
            .units
            .iter()
            .position(|ty| ty.flags & 0x0008_0000 != 0)
            .unwrap() as u16;
        let without_flag = w
            .data
            .units
            .iter()
            .position(|ty| ty.flags & 0x0008_0000 == 0)
            .unwrap() as u16;

        assert_eq!(w.a08_unit_type_owner_query(without_flag, 1), Ok(true));
        assert_eq!(w.a08_unit_type_owner_query(with_flag, 1), Ok(false));

        w.spawn(1, uid::MARINE, 320, 320).unwrap();
        assert_eq!(w.a08_unit_type_owner_query(with_flag, 1), Err(()));
        // The scan keys on the owner byte only, not on the queried type.
        assert_eq!(w.a08_unit_type_owner_query(with_flag, 0), Ok(false));
    }

    #[test]
    fn a08_tile_rounding_matches_the_recovered_floor_form() {
        // `0x005c5f9a`/`0x005c5fcd` share this rounding.
        assert_eq!(a08_tile_index(0), 0);
        assert_eq!(a08_tile_index(31), 0);
        assert_eq!(a08_tile_index(32), 1);
        assert_eq!(a08_tile_index(-1), 0, "negative pixels add 31 first");
        assert_eq!(a08_tile_index(-31), 0);
        assert_eq!(a08_tile_index(-32), -1);
        assert_eq!(a08_tile_index(-33), -1);
        assert_eq!(a08_tile_index(-64), -2);
    }

    #[test]
    fn a08_placement_tile_row_and_column_helpers_use_the_units_dat_box() {
        // `0x005c5f9a` (columns) and `0x005c5fcd` (rows).
        let w = test_world();
        let offset_x = w.unit_placement_x(uid::MARINE);
        let offset_y = w.unit_placement_y(uid::MARINE);

        assert!(w.a08_placement_tile_row_matches(96, 96 + offset_y, uid::MARINE));
        assert!(w.a08_placement_tile_row_matches(96, 96 + offset_y + 31, uid::MARINE));
        assert!(!w.a08_placement_tile_row_matches(96, 96 + offset_y + 32, uid::MARINE));

        assert_eq!(
            w.a08_placement_columns_differ(96, 96 + offset_x, uid::MARINE),
            Err(())
        );
        assert_eq!(
            w.a08_placement_columns_differ(96, 96 + offset_x + 32, uid::MARINE),
            Ok(())
        );
    }

    #[test]
    fn a08_sprite_flag_high_bit_preserves_the_low_bits() {
        // `0x005c5060`.
        assert_eq!(a08_set_sprite_flag_high_bit(0x00, true), 0x80);
        assert_eq!(a08_set_sprite_flag_high_bit(0x7f, true), 0xff);
        assert_eq!(a08_set_sprite_flag_high_bit(0xff, false), 0x7f);
        assert_eq!(a08_set_sprite_flag_high_bit(0x92, false), 0x12);
    }

    #[test]
    fn a08_first_nonempty_group_pick_skips_empty_counts() {
        // `0x005c6329`.
        assert_eq!(
            a08_first_nonempty_group_pick(&[0, 0, 3, 0, 0, 0], 7),
            Some((2, 1))
        );
        assert_eq!(
            a08_first_nonempty_group_pick(&[0, 1, 4, 0, 0, 0], 3),
            Some((1, 0)),
            "a single entry ignores the RNG"
        );
        assert_eq!(
            a08_first_nonempty_group_pick(&[0, 0, 0, 0, 0, 2], 0),
            Some((5, 0))
        );
        assert_eq!(a08_first_nonempty_group_pick(&[0; 6], 9), None);
    }

    #[test]
    fn a08_cheapest_candidate_keeps_the_first_minimum() {
        // `0x005c65d0`.
        assert_eq!(a08_cheapest_candidate(&[9, 3, 3, 7]), Some(1));
        assert_eq!(a08_cheapest_candidate(&[5]), Some(0));
        assert_eq!(a08_cheapest_candidate(&[]), None);
    }

    #[test]
    fn a08_order_selector_matches_add_on_and_the_nuke_rows() {
        // `0x005c7331`.
        let mut w = test_world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        // AX == 0x22 (Place Add-On) matches regardless of the unit order.
        assert!(w.units[marine].a08_order_matches_addon_or_nuke(0x22));
        assert!(!w.units[marine].a08_order_matches_addon_or_nuke(0x99));
        w.issue(w.units[marine].id, Order::HoldPosition).unwrap();
        // Hold Position is row 0x6a, neither 0x22 nor 0x7b..=0x81.
        assert!(!w.units[marine].a08_order_matches_addon_or_nuke(0x99));

        // Row 34 (Place Add-On) is selected directly by AX.
        assert!(a08_order_code_matches_addon_or_nuke(0x22, 0));
        assert!(a08_order_code_matches_addon_or_nuke(0x99, 0x7b));
        assert!(a08_order_code_matches_addon_or_nuke(0x99, 0x81));
        assert!(!a08_order_code_matches_addon_or_nuke(0x99, 0x7a));
        assert!(!a08_order_code_matches_addon_or_nuke(0x99, 0x82));
    }

    #[test]
    fn a08_nuke_and_special_row_selector() {
        // `0x005c740a`.
        for row in [0x7c, 0x7d, 0x90, 0xa2] {
            assert!(a08_is_nuke_or_special_row(row), "row {row:#x}");
        }
        for row in [0x00, 0x7b, 0x7e, 0x8f, 0x91, 0xa1, 0xa3, 0xffff] {
            assert!(!a08_is_nuke_or_special_row(row), "row {row:#x}");
        }
    }
}

// ===========================================================================
// Merged from src/translated/agent10.rs
// ===========================================================================
// Translation batch 10.
//
// Only this file is edited by the batch.  Every method below is an
// inherent helper on [`SimUnit`] (prefixed `a10_`) whose observable
// behaviour is recovered from a `decompiled_uncited` routine in
// `0x005d0000..=0x005dffff`.  The routines in that range are the retail
// status-panel / status-effect helpers, and the comments document the
// `CUnit` offsets each one touches.  None of them needs new persistent
// state: the existing [`crate::sim::Status`], [`SimUnit::production`] and
// [`SimUnit::connected_unit`] fields already model the retail storage.

impl SimUnit {
    /// `0x005d21a0` (`FUN_005d21a0`, size 13): reports whether
    /// `CUnit+0x08` is greater than `0xa00`.  Retail stores hit points in
    /// 1/256 points, so `0xa00` is ten whole points; the predicate is used
    /// by the status panel to decide whether the unit is above that
    /// threshold.
    ///
    /// [`SimUnit::hp`] uses the same 1/256 fixed-point scale as the retail
    /// field, so the comparison is exact.
    pub fn a10_hp_above_ten(&self) -> bool {
        self.hp > 0xa00
    }

    /// `0x005d26a0` (`FUN_005d26a0`, size 18): the routine aborts when
    /// `CUnit+0x114` is nonzero.  That byte is the remaining Defensive
    /// Matrix status-update count, so the translated predicate reports
    /// whether a matrix is currently running on the unit.
    pub fn a10_defensive_matrix_active(&self) -> bool {
        self.status.matrix_ticks != 0
    }

    /// `0x005d27da` (`FUN_005d27da`, size 18): compiled conditional store
    /// (`cmovbe`-style) into the lockdown timer `CUnit+0x117`.  The value
    /// already in the timer is kept unless the comparison flags say
    /// below-or-equal (`CF || ZF`), in which case `candidate` is written.
    /// Returns the byte that was stored.
    ///
    /// The retail byte store truncates the current value to its low eight
    /// bits; that is reproduced here before the conditional selection.
    pub fn a10_store_lockdown_ticks_if(&mut self, candidate: u8, below_or_equal: bool) -> u8 {
        let existing = self.status.lockdown_ticks as u8;
        let stored = if below_or_equal { candidate } else { existing };
        self.status.lockdown_ticks = i32::from(stored);
        stored
    }

    /// `0x005d22bf` (`FUN_005d22bf`, size 56): after the death/removal
    /// sound is queued, the routine tests `CUnit+0x126` and, when it is
    /// nonzero, calls `FUN_005dc4a0` to wipe every acid-spore stack.
    /// Reproduces exactly that observable effect and reports whether any
    /// stack was present.
    pub fn a10_clear_acid_spores_if_present(&mut self) -> bool {
        if self.status.acid_spores == 0 {
            return false;
        }
        self.status.clear_acid_spores();
        true
    }

    /// `0x005dc5e0` (`FUN_005dc5e0`, size 65): plague status cue.  When
    /// `CUnit+0x11a` is nonzero the routine temporarily zeroes the timer,
    /// plays cue `0x184 + (local_player & 0xff)` for a unit that has not
    /// finished construction (`FUN_005b5840` is the `CUnit+0xdc` bit-4
    /// "completed" flag), and restores the timer.  The timer therefore
    /// never changes; the observable result is the cue id, which this
    /// helper returns.
    pub fn a10_plague_sound_cue(&self, player: u8) -> Option<u16> {
        if self.status.plague_ticks != 0 && !self.completed {
            Some(0x184 + u16::from(player))
        } else {
            None
        }
    }

    /// `0x005dc630` (`FUN_005dc630`, size 68): acid-spore status cue.
    /// When `CUnit+0x126` is nonzero the routine derives a variant
    /// `min(count / 2, 3)` and plays cue
    /// `0x3da + (local_player & 0xff) * 4 + variant`.  The helper returns
    /// the same cue id without playing it.
    pub fn a10_acid_spore_sound_cue(&self, player: u8) -> Option<u16> {
        if self.status.acid_spores == 0 {
            return None;
        }
        let variant = (u16::from(self.status.acid_spores) >> 1).min(3);
        Some(0x3da + u16::from(player) * 4 + variant)
    }

    /// `0x005dc680` (`FUN_005dc680`, size 79): ensnare status cue.  When
    /// `CUnit+0x116` is nonzero the routine temporarily saves the timer,
    /// zeroes it, queues cue `0x180 + (local_player & 0xff)` for a unit
    /// that is not complete, writes `0x4b`, calls the noreturn
    /// `FUN_005da480`, and restores the saved timer.  The timer is
    /// unchanged; the observable result is the cue id.
    pub fn a10_ensnare_sound_cue(&self, player: u8) -> Option<u16> {
        if self.status.ensnare_ticks != 0 && !self.completed {
            Some(0x180 + u16::from(player))
        } else {
            None
        }
    }

    /// `0x005dcb50` (`FUN_005dcb50`, size 40): returns 1 when
    /// `CUnit+0x80` (the Hatchery/Lair/Hive owning this larva) is null and
    /// otherwise reaches a noreturn error.  Translated as the ownership
    /// predicate.
    pub fn a10_larva_orphaned(&self) -> bool {
        self.connected_unit.is_none()
    }

    /// `0x005d5c30` (`FUN_005d5c30`, size 68): reads the 16-bit unit type
    /// from production-queue slot `param_1` at `CUnit+0xb0 + param_1 * 2`.
    /// The retail routine also folds the two per-slot state bits from
    /// `CUnit+0x132` into the high half when `FUN_0060b560()` reports a
    /// Brood War build; those state bits are not modeled by
    /// [`SimUnit::production`], so the translated getter returns the
    /// queued unit type and `None` for an empty or non-training slot.
    pub fn a10_production_slot_type(&self, slot: usize) -> Option<u16> {
        match self.production.get(slot) {
            Some(Order::Train { unit_type }) => Some(*unit_type),
            _ => None,
        }
    }

    /// `0x005d423a` (`FUN_005d423a`, size 52): remaps the incoming
    /// 16-bit unit/button id before `FUN_005afa00` receives it:
    /// `0x19 -> 0x17` and `0x1e -> 5`; every other id is passed through.
    pub fn a10_remap_button_unit_id(id: u16) -> u16 {
        match id {
            0x19 => 0x17,
            0x1e => 5,
            other => other,
        }
    }
}

#[cfg(test)]
mod tests_agent10 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::World;
    use std::sync::Arc;

    fn open_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World) -> usize {
        world.spawn_px(0, uid::MARINE, 640, 640).unwrap()
    }

    #[test]
    fn hp_threshold_is_ten_whole_points() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].hp = 0xa00;
        assert!(!w.units[i].a10_hp_above_ten(), "exactly ten points");
        w.units[i].hp = 0xa01;
        assert!(w.units[i].a10_hp_above_ten(), "just above ten points");
        w.units[i].hp = 0;
        assert!(!w.units[i].a10_hp_above_ten());
    }

    #[test]
    fn defensive_matrix_predicate_reads_the_status_timer() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].status.matrix_ticks = 0;
        assert!(!w.units[i].a10_defensive_matrix_active());
        w.units[i].status.matrix_ticks = 0xa8;
        assert!(w.units[i].a10_defensive_matrix_active());
    }

    #[test]
    fn lockdown_store_keeps_or_replaces_the_byte() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].status.lockdown_ticks = 5;
        // above-or-equal comparison: the existing timer stays.
        assert_eq!(w.units[i].a10_store_lockdown_ticks_if(9, false), 5);
        assert_eq!(w.units[i].status.lockdown_ticks, 5);
        // below-or-equal: the candidate is written.
        assert_eq!(w.units[i].a10_store_lockdown_ticks_if(9, true), 9);
        assert_eq!(w.units[i].status.lockdown_ticks, 9);
        // The retail store is a byte write: keep only the low eight bits.
        w.units[i].status.lockdown_ticks = 0x1_0105;
        assert_eq!(w.units[i].a10_store_lockdown_ticks_if(0, false), 5);
    }

    #[test]
    fn acid_spore_cleanup_reports_and_clears_every_stack() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].status.acid_spores = 0;
        assert!(!w.units[i].a10_clear_acid_spores_if_present());
        w.units[i].status.acid_spores = 3;
        w.units[i].status.acid_spore_ticks[0] = 40;
        assert!(w.units[i].a10_clear_acid_spores_if_present());
        assert_eq!(w.units[i].status.acid_spores, 0);
        assert_eq!(w.units[i].status.acid_spore_ticks, [0; 9]);
        assert!(!w.units[i].a10_clear_acid_spores_if_present());
    }

    #[test]
    fn plague_cue_only_for_active_unfinished_units() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].status.plague_ticks = 0;
        assert_eq!(w.units[i].a10_plague_sound_cue(2), None);
        w.units[i].status.plague_ticks = 100;
        w.units[i].completed = false;
        assert_eq!(w.units[i].a10_plague_sound_cue(2), Some(0x184 + 2));
        w.units[i].completed = true;
        assert_eq!(w.units[i].a10_plague_sound_cue(2), None);
    }

    #[test]
    fn acid_spore_cue_scales_with_count_and_player() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].status.acid_spores = 0;
        assert_eq!(w.units[i].a10_acid_spore_sound_cue(1), None);
        w.units[i].status.acid_spores = 1;
        assert_eq!(w.units[i].a10_acid_spore_sound_cue(1), Some(0x3da + 4));
        w.units[i].status.acid_spores = 7;
        assert_eq!(w.units[i].a10_acid_spore_sound_cue(1), Some(0x3da + 4 + 3));
        w.units[i].status.acid_spores = 9;
        assert_eq!(w.units[i].a10_acid_spore_sound_cue(0), Some(0x3da + 3));
        w.units[i].status.acid_spores = 4;
        assert_eq!(w.units[i].a10_acid_spore_sound_cue(3), Some(0x3da + 12 + 2));
    }

    #[test]
    fn ensnare_cue_only_for_active_unfinished_units() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].status.ensnare_ticks = 0;
        assert_eq!(w.units[i].a10_ensnare_sound_cue(0), None);
        w.units[i].status.ensnare_ticks = 75;
        w.units[i].completed = false;
        assert_eq!(w.units[i].a10_ensnare_sound_cue(0), Some(0x180));
        w.units[i].completed = true;
        assert_eq!(w.units[i].a10_ensnare_sound_cue(1), None);
    }

    #[test]
    fn larva_is_orphaned_without_a_hatchery_link() {
        let mut w = open_world();
        let i = spawn(&mut w);
        w.units[i].connected_unit = None;
        assert!(w.units[i].a10_larva_orphaned());
        w.units[i].connected_unit = Some(42);
        assert!(!w.units[i].a10_larva_orphaned());
    }

    #[test]
    fn production_slots_expose_only_queued_training_types() {
        let mut w = open_world();
        let i = spawn(&mut w);
        assert_eq!(w.units[i].a10_production_slot_type(0), None);
        w.units[i].production.push_back(Order::Train {
            unit_type: uid::MARINE,
        });
        w.units[i].production.push_back(Order::Train {
            unit_type: uid::SCV,
        });
        assert_eq!(w.units[i].a10_production_slot_type(0), Some(uid::MARINE));
        assert_eq!(w.units[i].a10_production_slot_type(1), Some(uid::SCV));
        assert_eq!(w.units[i].a10_production_slot_type(2), None);
        assert_eq!(w.units[i].a10_production_slot_type(usize::MAX), None);
    }

    #[test]
    fn button_id_remap_matches_the_retail_table() {
        assert_eq!(SimUnit::a10_remap_button_unit_id(0x19), 0x17);
        assert_eq!(SimUnit::a10_remap_button_unit_id(0x1e), 5);
        assert_eq!(SimUnit::a10_remap_button_unit_id(0x18), 0x18);
        assert_eq!(SimUnit::a10_remap_button_unit_id(0), 0);
    }
}

// ===========================================================================
// Merged from src/translated/agent13.rs
// ===========================================================================
// Translation batch 13.  Only this file is edited by the batch.
//
// Recovered `CUnit` helpers in `0x005b0000..=0x005b3fff` whose persistent
// effect lands on fields the Rust model already stores.  Retail keeps the
// death list and the sprite lists out of the unit record, so the routines
// that only splice list pointers have no separate Rust state; the methods
// below model the record-level effects that survive in [`World`] and
// [`SimUnit`].

impl World {
    /// `0x005b0d20`: head of the removed-unit (death) list (`0x00fa3700`).
    ///
    /// Death cleanup and the subunit removal path splice a record into this
    /// list with the insert-behind-head helper, so the head stays on the
    /// first record that reached the list.  [`World::units`] keeps dead
    /// records in spawn order and never removes them, so the first unit with
    /// [`SimUnit::alive`] clear is that head.
    pub fn a13_first_dead_unit(&self) -> Option<u32> {
        self.units
            .iter()
            .find(|unit| !unit.alive)
            .map(|unit| unit.id)
    }
}

impl SimUnit {
    /// `0x005b0b4b`: clear the `CUnit+0xdc` bit-0 "ready/completed" flag.
    ///
    /// The routine is the removal counterpart of the construction finisher:
    /// it clears bit 0 of the state dword and returns the unit type id.  In
    /// the Rust model that bit is [`SimUnit::completed`].  Retail also asks
    /// for a command-card refresh and clears a presentation-only shield
    /// flag, neither of which has a persistent model field.
    pub fn a13_clear_completed_flag(&mut self) {
        self.completed = false;
    }

    /// `0x005b3910`: recovery-side construction hit-point rate at
    /// `CUnit+0xa8`.
    ///
    /// Retail divides the type's maximum raw hit points less the ten-percent
    /// construction discount, minus one, plus the build time by the build
    /// time (integer division, both operands positive):
    ///
    /// `rate = (hp - hp / 10 - 1 + build_time) / build_time`
    ///
    /// and clamps the result to one.  The engine recomputes this gain inside
    /// `update_construction` instead of caching it, so the method returns the
    /// value rather than storing `CUnit+0xa8`.
    pub fn a13_construction_hp_rate(&self, data: &GameData) -> i16 {
        let ty = data.unit(self.type_id);
        let hp = ty.hit_points_raw as i32;
        let build = i32::from(ty.build_time);
        if build != 0 {
            let rate = (hp - hp / 10 - 1 + build) / build;
            if rate != 0 {
                return rate.clamp(i16::MIN as i32, i16::MAX as i32) as i16;
            }
        }
        1
    }

    /// `0x005b0380`: copy the unit's status-effect block from another
    /// record.
    ///
    /// Retail copies the words and bytes at `CUnit+0x110..+0x12f` verbatim:
    /// the death timer, the Defensive Matrix counter, the psi-storm guard,
    /// the per-unit masks, the Maelstrom timer, the Acid Spore count and the
    /// nine Acid Spore lifetime slots.  Those are exactly the fields held by
    /// [`SimUnit::death_timer`] and [`SimUnit::status`], so the modelled
    /// subset is cloned in one step.  The raw block also covers a handful of
    /// bytes with no Rust field; they are not represented here.
    pub fn a13_copy_status_block_from(&mut self, other: &SimUnit) {
        self.death_timer = other.death_timer;
        self.status = other.status.clone();
    }

    /// `0x005b3220`: drop the linked order target while no overlay is
    /// active.
    ///
    /// If `CUnit+0xe0` is non-zero the routine returns immediately.  Otherwise
    /// it clears that overlay byte, and when the linked target at `CUnit+0xc0`
    /// is non-zero it sets bit 2 of the order/state byte `CUnit+0x93` before
    /// dropping the link.  The Rust model derives the linked target from the
    /// current order's unit slot, so the link is cleared with
    /// [`SimUnit::clear_order_target`]; the return value says whether a link
    /// was present.  Retail additionally refreshes a command-card lookup,
    /// which is presentation-only.
    pub fn a13_clear_idle_link(&mut self) -> bool {
        if self.overlay_flags != 0 {
            return false;
        }
        let linked = self.order_unit_target();
        if let Some(id) = linked {
            self.flags_93 |= 4;
            self.clear_order_target(id);
        }
        self.overlay_flags = 0;
        linked.is_some()
    }

    /// `0x005b1239`: restore the unit's all-visible mask (`CUnit+0xe4`).
    ///
    /// The handler writes `0xffffffff` to the per-player visibility mask and
    /// reports success.  Retail also releases the sprite image and gates a
    /// voice line on the current order being row `0x23`; the mask is the only
    /// persistent state the model stores, and the sprite is owned by the
    /// renderer rather than [`SimUnit`].
    pub fn a13_restore_visibility(&mut self) -> bool {
        self.visibility_mask = u32::MAX;
        true
    }
}

#[cfg(test)]
mod tests_agent13 {
    use super::*;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::Order;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    /// `0x005b0d20`: the death-list head is the oldest dead record, and live
    /// units are never part of that view.
    #[test]
    fn dead_list_head_is_the_oldest_dead_unit() {
        let mut w = world();
        let first = w.spawn(0, uid::MARINE, 10, 10).unwrap();
        let second = w.spawn(0, uid::MARINE, 20, 10).unwrap();
        let third = w.spawn(1, uid::SCV, 30, 10).unwrap();

        assert_eq!(w.a13_first_dead_unit(), None);

        w.units[second].alive = false;
        assert_eq!(w.a13_first_dead_unit(), Some(w.units[second].id));

        w.units[first].alive = false;
        assert_eq!(w.a13_first_dead_unit(), Some(w.units[first].id));

        w.units[third].alive = false;
        assert_eq!(w.a13_first_dead_unit(), Some(w.units[first].id));
    }

    /// `0x005b0b4b`: only the completion bit is dropped; hit points are left
    /// for the removal path.
    #[test]
    fn clearing_completed_bit_leaves_hit_points_alone() {
        let mut w = world();
        let u = w.spawn(0, uid::BARRACKS, 24, 24).unwrap();
        w.units[u].completed = true;
        w.units[u].hp = 333;

        w.units[u].a13_clear_completed_flag();

        assert!(!w.units[u].completed);
        assert_eq!(w.units[u].hp, 333);
    }

    /// `0x005b3910`: the stored construction rate matches the retail
    /// integer formula and is never zero.
    #[test]
    fn construction_hp_rate_matches_retail_formula() {
        let mut w = world();
        for type_id in [uid::MARINE, uid::BARRACKS, uid::COMMAND_CENTER] {
            let u = w.spawn(0, type_id, 32, 32).unwrap();
            let ty = w.data.unit(type_id);
            let hp = ty.hit_points_raw as i32;
            let build = i32::from(ty.build_time);
            let expected = if build == 0 {
                1
            } else {
                let rate = (hp - hp / 10 - 1 + build) / build;
                rate.max(1) as i16
            };

            let rate = w.units[u].a13_construction_hp_rate(&w.data);
            assert_eq!(rate, expected, "type {type_id:#x}");
            assert!(rate >= 1, "type {type_id:#x}");
        }
    }

    /// `0x005b0380`: the death timer and the whole Status block move to the
    /// destination while the source keeps its values.
    #[test]
    fn status_block_copy_moves_modelled_effect_state() {
        let mut w = world();
        let source = w.spawn(0, uid::MARINE, 10, 10).unwrap();
        let dest = w.spawn(1, uid::MARINE, 20, 10).unwrap();

        w.units[dest].death_timer = 1;
        w.units[dest].status.matrix = 0;
        w.units[dest].status.acid_spores = 0;

        w.units[source].death_timer = 37;
        w.units[source].status.matrix = 512;
        w.units[source].status.matrix_ticks = 0xa8;
        w.units[source].status.acid_spores = 2;
        w.units[source].status.acid_spore_ticks[0] = 0x96;
        w.units[source].status.psi_storm_guard = 1;
        w.units[source].status.status_mask_121 = 0x12;
        w.units[source].status.status_mask_123 = 0x34;
        w.units[source].status.maelstrom_ticks = 0x16;
        w.units[source].status.parasite = true;
        w.units[source].status.cloaked = true;

        let donor = w.units[source].clone();
        w.units[dest].a13_copy_status_block_from(&donor);

        assert_eq!(w.units[dest].death_timer, 37);
        assert_eq!(w.units[dest].status.matrix, 512);
        assert_eq!(w.units[dest].status.matrix_ticks, 0xa8);
        assert_eq!(w.units[dest].status.acid_spores, 2);
        assert_eq!(w.units[dest].status.acid_spore_ticks[0], 0x96);
        assert_eq!(w.units[dest].status.psi_storm_guard, 1);
        assert_eq!(w.units[dest].status.status_mask_121, 0x12);
        assert_eq!(w.units[dest].status.status_mask_123, 0x34);
        assert_eq!(w.units[dest].status.maelstrom_ticks, 0x16);
        assert!(w.units[dest].status.parasite);
        assert!(w.units[dest].status.cloaked);

        // The source is untouched.
        assert_eq!(w.units[source].death_timer, 37);
        assert_eq!(w.units[source].status.matrix, 512);
    }

    /// `0x005b3220`: an active overlay blocks the cleanup; otherwise the
    /// linked target is dropped and bit 2 of `CUnit+0x93` is recorded.
    #[test]
    fn idle_link_cleanup_drops_target_only_without_overlay() {
        let mut w = world();
        let scv = w.spawn(0, uid::SCV, 10, 10).unwrap();
        let mineral = w.spawn(0, uid::MINERAL_FIELD, 20, 10).unwrap();
        let target = w.units[mineral].id;

        w.units[scv].overlay_flags = 1;
        w.units[scv].order = Order::Gather { resource: target };
        assert!(!w.units[scv].a13_clear_idle_link());
        assert_eq!(w.units[scv].order_unit_target(), Some(target));
        assert_eq!(w.units[scv].overlay_flags, 1);
        assert_eq!(w.units[scv].flags_93 & 4, 0);

        w.units[scv].overlay_flags = 0;
        assert!(w.units[scv].a13_clear_idle_link());
        assert_eq!(w.units[scv].order_unit_target(), None);
        assert!(matches!(w.units[scv].order, Order::Idle));
        assert_eq!(w.units[scv].flags_93 & 4, 4);

        // Nothing left to clear.
        assert!(!w.units[scv].a13_clear_idle_link());
    }

    /// `0x005b1239`: the visibility mask is restored to all ones and the
    /// handler reports success.
    #[test]
    fn visibility_restore_sets_every_player_bit() {
        let mut w = world();
        let u = w.spawn(1, uid::MARINE, 12, 12).unwrap();
        w.units[u].visibility_mask = 0;

        assert!(w.units[u].a13_restore_visibility());
        assert_eq!(w.units[u].visibility_mask, u32::MAX);
        assert!(w.units[u].a13_restore_visibility());
    }
}

