// Translation batch 38.  Only this file is edited by the batch.
//
// Coverage: the `decompiled_uncited` rows of `0x005de000..=0x005dffff`.
// Most of that window is the client's runtime-integrity / obfuscation
// island: the recovered listings there land inside encrypted blocks,
// overlapping instructions, inline jump-table arms and libc++ exception
// cleanup thunks.  The rows translated here are the ones with recoverable
// behaviour: the Hatchery larva-placement arms and their four side probes,
// the placement fallback's half-width probe, plus the small
// placement-callback echo block.
//
// The placement arms write a freshly created Larva's unmodelled `+0x4e`
// order-state byte (the spawn side) and read the Hatchery's four
// `+0xd0..+0xd6` side scores.  The sim keeps the scores in
// [`SimUnit::larva_spawn_side_values`] as `[left, top, right, bottom]`; the
// state byte is returned to the caller instead of being added as a field.

impl World {
    /// Bounding box `(left, top, right, bottom)` of a unit in whole pixels,
    /// built from that unit type's `units.dat` extents.  This is the box the
    /// placement arms compare the newly created Larva against.
    fn a38_hatch_box(&self, hatch_id: u32) -> Option<(i32, i32, i32, i32)> {
        let hatch = self.unit(hatch_id)?;
        let dims = self.data.unit(hatch.type_id).dimensions;
        Some(dims.rect_at((hatch.x / fp(1), hatch.y / fp(1))))
    }

    /// One of the Hatchery's four side scores, in the retail order
    /// `[left, top, right, bottom]`.  The scores are 16-bit values in retail
    /// and the initial "no side" screen is 101 (`0x65`).
    fn a38_side_score(&self, hatch_id: u32, slot: usize) -> u16 {
        self.unit(hatch_id)
            .map(|u| u.larva_spawn_side_values[slot] as u16)
            .unwrap_or(0x65)
    }

    /// The larva-placement clearance test shared by the four side arms: the
    /// candidate must be on the map and on creep, and its neighbour `(dx,
    /// dy)` away must be on the map and walkable or crepuscular.  Retail
    /// probes the neighbour 22 px away along the side's outward axis.
    fn a38_spot_clear(&mut self, pos: (i32, i32), dx: i32, dy: i32) -> bool {
        let max_x = self.terrain.width as i32 * 32;
        let max_y = self.terrain.height as i32 * 32;
        let inside = |x: i32, y: i32| (0..max_x).contains(&x) && (0..max_y).contains(&y);
        if !inside(pos.0, pos.1) {
            return false;
        }
        let neighbour = (pos.0 + dx, pos.1 + dy);
        if !inside(neighbour.0, neighbour.1) {
            return false;
        }
        self.has_creep_px(pos.0, pos.1)
            && (self.terrain.walkable_px(neighbour.0, neighbour.1)
                || self.has_creep_px(neighbour.0, neighbour.1))
    }

    /// `0x005dfabc`: first arm of the spawn-side chain.  A newly created
    /// Larva whose X lies left of the Hatchery's box records order-state byte
    /// `0`; otherwise control falls through to the next arm.
    ///
    /// `None` means "no write" (the retail code jumps to the Y test), not an
    /// error; a missing unit also yields `None`.
    pub fn a38_hatch_state_left(&self, hatch_id: u32, x: i32) -> Option<u8> {
        let (left, _, _, _) = self.a38_hatch_box(hatch_id)?;
        (x < left).then_some(0)
    }

    /// `0x005dfad4`: second arm of the spawn-side chain.  A Larva whose Y
    /// lies above the Hatchery's box records order-state byte `1`; otherwise
    /// control falls through to the final arm.
    pub fn a38_hatch_state_top(&self, hatch_id: u32, y: i32) -> Option<u8> {
        let (_, top, _, _) = self.a38_hatch_box(hatch_id)?;
        (y < top).then_some(1)
    }

    /// `0x005dfaec`: final, unconditional arm of the spawn-side chain.  It
    /// records `2` when X is at or left of the Hatchery's right edge (the
    /// right side) and `3` when X is beyond it (the bottom side).
    pub fn a38_hatch_state_right_or_bottom(&self, hatch_id: u32, x: i32) -> Option<u8> {
        let (_, _, right, _) = self.a38_hatch_box(hatch_id)?;
        Some(if x <= right { 2 } else { 3 })
    }

    /// `0x005dfe56`: bottom-side larva spot.  When the bottom score
    /// (`larva_spawn_side_values[3]`) is below both the running best and the
    /// initial 101 screen, probe `(hatch_x, box_bottom + 10)` with the
    /// neighbour 22 px further down.  Returns the accepted point and the
    /// score it replaced the running best with.
    pub fn a38_larva_spot_bottom(
        &mut self,
        hatch_id: u32,
        best_score: u16,
    ) -> Option<(i32, i32, u16)> {
        let (_, _, _, bottom) = self.a38_hatch_box(hatch_id)?;
        let hx = self.unit(hatch_id)?.x / fp(1);
        let score = self.a38_side_score(hatch_id, 3);
        if score >= 0x65 || score >= best_score {
            return None;
        }
        let pos = (hx, bottom + 10);
        self.a38_spot_clear(pos, 0, 22)
            .then_some((pos.0, pos.1, score))
    }

    /// `0x005dfeb5`: left-side larva spot.  When the left score
    /// (`larva_spawn_side_values[0]`) beats the running best, probe
    /// `(box_left - 10, hatch_y)` with the neighbour 22 px further left.
    pub fn a38_larva_spot_left(
        &mut self,
        hatch_id: u32,
        best_score: u16,
    ) -> Option<(i32, i32, u16)> {
        let (left, _, _, _) = self.a38_hatch_box(hatch_id)?;
        let hy = self.unit(hatch_id)?.y / fp(1);
        let score = self.a38_side_score(hatch_id, 0);
        if score >= best_score {
            return None;
        }
        let pos = (left - 10, hy);
        self.a38_spot_clear(pos, -22, 0)
            .then_some((pos.0, pos.1, score))
    }

    /// `0x005dff07`: right-side larva spot.  When the right score
    /// (`larva_spawn_side_values[2]`) beats the running best, probe
    /// `(box_right + 10, hatch_y)` with the neighbour 22 px further right.
    pub fn a38_larva_spot_right(
        &mut self,
        hatch_id: u32,
        best_score: u16,
    ) -> Option<(i32, i32, u16)> {
        let (_, _, right, _) = self.a38_hatch_box(hatch_id)?;
        let hy = self.unit(hatch_id)?.y / fp(1);
        let score = self.a38_side_score(hatch_id, 2);
        if score >= best_score {
            return None;
        }
        let pos = (right + 10, hy);
        self.a38_spot_clear(pos, 22, 0)
            .then_some((pos.0, pos.1, score))
    }

    /// `0x005dff4c`: top-side larva spot and the final return of the four
    /// side arms.  When the top score (`larva_spawn_side_values[1]`) beats
    /// the running best, probe `(hatch_x, box_top - 10)` with the neighbour
    /// 22 px further up.  A rejected top probe returns `None`, which is the
    /// retail `best` flag being clear.
    pub fn a38_larva_spot_top(
        &mut self,
        hatch_id: u32,
        best_score: u16,
    ) -> Option<(i32, i32, u16)> {
        let (_, top, _, _) = self.a38_hatch_box(hatch_id)?;
        let hx = self.unit(hatch_id)?.x / fp(1);
        let score = self.a38_side_score(hatch_id, 1);
        if score >= best_score {
            return None;
        }
        let pos = (hx, top - 10);
        self.a38_spot_clear(pos, 0, -22)
            .then_some((pos.0, pos.1, score))
    }

    /// `0x005dffcc`: half the Hatchery's pixel width, `(left + right + 1) /
    /// 2`.  This is the offset the bottom fallback probes use when all four
    /// box sides are rejected.
    pub fn a38_hatch_half_width(&self, hatch_id: u32) -> Option<i32> {
        let hatch = self.unit(hatch_id)?;
        let (left, _, right, _) = self.data.unit(hatch.type_id).dimensions.extents();
        Some((left + right + 1) / 2)
    }

    /// `0x005dffe0`: bottom fallback larva spot at the Hatchery centre plus
    /// its half width.  The probe is the same bottom-side clearance test;
    /// the bottom score is recorded without another comparison because this
    /// arm only runs after every side probe failed.
    pub fn a38_larva_spot_bottom_right_half(&mut self, hatch_id: u32) -> Option<(i32, i32, u16)> {
        let (_, _, _, bottom) = self.a38_hatch_box(hatch_id)?;
        let hx = self.unit(hatch_id)?.x / fp(1);
        let half = self.a38_hatch_half_width(hatch_id)?;
        let score = self.a38_side_score(hatch_id, 3);
        let pos = (hx + half, bottom + 10);
        self.a38_spot_clear(pos, 0, 22)
            .then_some((pos.0, pos.1, score))
    }

    /// `0x005df950`: placement-callback echo.  The recovered block invokes
    /// the caller's placement callback with request code `-1` and the record
    /// id; when the callback reports success (a non-negative result) it
    /// copies the 28-byte placement record to the output before running the
    /// follow-up.  The follow-up itself is in the obfuscated tail and is not
    /// reconstructed, so only the successful record copy is returned.
    pub fn a38_placement_echo<F>(
        &self,
        request: u32,
        record: [u8; 28],
        callback: F,
    ) -> Option<[u8; 28]>
    where
        F: FnOnce(i32, u32) -> i32,
    {
        (callback(-1, request) >= 0).then_some(record)
    }
}

#[cfg(test)]
mod tests_agent38 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, type_id: u16) -> usize {
        world.spawn(0, type_id, 320, 320).expect("spawn")
    }

    fn hatch_box(w: &World, slot: usize) -> (i32, i32, i32, i32) {
        let u = &w.units[slot];
        w.data
            .unit(u.type_id)
            .dimensions
            .rect_at((u.x / fp(1), u.y / fp(1)))
    }

    #[test]
    fn hatch_state_chain_uses_the_parent_box() {
        let mut w = world();
        let hatch = spawn(&mut w, uid::HATCHERY);
        let (left, top, right, _) = hatch_box(&w, hatch);
        let id = w.units[hatch].id;

        assert_eq!(w.a38_hatch_state_left(id, left - 1), Some(0));
        assert_eq!(w.a38_hatch_state_left(id, left), None);
        assert_eq!(w.a38_hatch_state_top(id, top - 1), Some(1));
        assert_eq!(w.a38_hatch_state_top(id, top), None);
        assert_eq!(w.a38_hatch_state_right_or_bottom(id, right), Some(2));
        assert_eq!(w.a38_hatch_state_right_or_bottom(id, right - 50), Some(2));
        assert_eq!(w.a38_hatch_state_right_or_bottom(id, right + 1), Some(3));
    }

    #[test]
    fn hatch_state_chain_returns_none_for_an_unknown_unit() {
        let w = world();
        assert_eq!(w.a38_hatch_state_left(0xdead_beef, 0), None);
        assert_eq!(w.a38_hatch_state_top(0xdead_beef, 0), None);
        assert_eq!(w.a38_hatch_state_right_or_bottom(0xdead_beef, 0), None);
    }

    #[test]
    fn bottom_spot_is_taken_below_the_box() {
        let mut w = world();
        let hatch = spawn(&mut w, uid::HATCHERY);
        let (_, _, _, bottom) = hatch_box(&w, hatch);
        let hx = w.units[hatch].x / fp(1);
        let id = w.units[hatch].id;
        w.mature_creep();
        w.units[hatch].larva_spawn_side_values = [40, 40, 40, 7];

        assert_eq!(
            w.a38_larva_spot_bottom(id, 0x65),
            Some((hx, bottom + 10, 7))
        );
    }

    #[test]
    fn side_scores_gate_the_probes() {
        let mut w = world();
        let hatch = spawn(&mut w, uid::HATCHERY);
        let id = w.units[hatch].id;
        let (left, _, _, _) = hatch_box(&w, hatch);
        let hy = w.units[hatch].y / fp(1);
        w.mature_creep();

        w.units[hatch].larva_spawn_side_values = [101, 101, 101, 101];
        assert_eq!(w.a38_larva_spot_bottom(id, 0x65), None);
        assert_eq!(w.a38_larva_spot_left(id, 0x65), None);
        assert_eq!(w.a38_larva_spot_right(id, 0x65), None);
        assert_eq!(w.a38_larva_spot_top(id, 0x65), None);

        w.units[hatch].larva_spawn_side_values = [4, 3, 2, 1];
        assert_eq!(w.a38_larva_spot_left(id, 4), None);
        assert_eq!(w.a38_larva_spot_left(id, 5), Some((left - 10, hy, 4)));
    }

    #[test]
    fn left_right_and_top_spots_sit_outside_the_box() {
        let mut w = world();
        let hatch = spawn(&mut w, uid::HATCHERY);
        let (left, top, right, _) = hatch_box(&w, hatch);
        let hy = w.units[hatch].y / fp(1);
        let hx = w.units[hatch].x / fp(1);
        let id = w.units[hatch].id;
        w.mature_creep();
        w.units[hatch].larva_spawn_side_values = [1, 2, 3, 4];

        assert_eq!(w.a38_larva_spot_left(id, 0x65), Some((left - 10, hy, 1)));
        assert_eq!(w.a38_larva_spot_right(id, 0x65), Some((right + 10, hy, 3)));
        assert_eq!(w.a38_larva_spot_top(id, 0x65), Some((hx, top - 10, 2)));
    }

    #[test]
    fn a_non_creep_source_does_not_produce_a_spot() {
        let mut w = world();
        let marine = spawn(&mut w, uid::MARINE);
        let id = w.units[marine].id;
        assert_eq!(w.a38_larva_spot_bottom(id, 0x65), None);
        assert_eq!(w.a38_larva_spot_left(id, 0x65), None);
        assert_eq!(w.a38_larva_spot_right(id, 0x65), None);
        assert_eq!(w.a38_larva_spot_top(id, 0x65), None);
    }

    #[test]
    fn half_width_is_the_retail_span() {
        let mut w = world();
        let hatch = spawn(&mut w, uid::HATCHERY);
        let (left, _, right, _) = hatch_box(&w, hatch);
        let id = w.units[hatch].id;
        // The box halves are the stored extents; the recovered helper adds
        // them, adds one and halves the sum.
        let extents = w.data.unit(uid::HATCHERY).dimensions.extents();
        assert_eq!(
            w.a38_hatch_half_width(id),
            Some((extents.0 + extents.2 + 1) / 2)
        );
        assert!(right > left);
    }

    #[test]
    fn bottom_right_half_spot_uses_the_half_width() {
        let mut w = world();
        let hatch = spawn(&mut w, uid::HATCHERY);
        let (_, _, _, bottom) = hatch_box(&w, hatch);
        let hx = w.units[hatch].x / fp(1);
        let id = w.units[hatch].id;
        w.mature_creep();
        w.units[hatch].larva_spawn_side_values = [0, 0, 0, 9];
        let half = w.a38_hatch_half_width(id).unwrap();

        assert_eq!(
            w.a38_larva_spot_bottom_right_half(id),
            Some((hx + half, bottom + 10, 9))
        );
    }

    #[test]
    fn placement_echo_copies_only_on_success() {
        let w = world();
        let record = [0x5au8; 28];
        let mut seen = None;
        let echoed = w.a38_placement_echo(7, record, |code, request| {
            seen = Some((code, request));
            0
        });
        assert_eq!(seen, Some((-1, 7)));
        assert_eq!(echoed, Some(record));

        let rejected = w.a38_placement_echo(9, record, |_, _| -1);
        assert_eq!(rejected, None);
    }
}

// ===========================================================================
// Merged from src/translated/agent39.rs
// ===========================================================================
// Translation batch 39.  Only this file is edited by the batch.
//
// The `decompiled_uncited` rows in `0x005e0000..=0x005e1fff` fall into two
// groups.  The `0x005e00xx`/`0x005e04xx`/`0x005e08xx` rows are fragments of
// the Zerg hatchery's larva spawn-side scan (the four per-side scores that
// [`SimUnit::larva_spawn_side_values`] already stores); the `0x005e0bxx` rows
// are the scenario countdown-text arithmetic.  Everything else in the page is
// MSVC exception-unwinding funclets, tail-call thunks or jump-table targets
// that the decompiler split out with bad control flow (several decode into
// `halt_baddata`); those are recorded as skipped rather than guessed.
//
// Only record-level behaviour the existing [`World`]/[`SimUnit`] state can
// hold is translated here.  Retail's failure branches call a noreturn abort
// helper; they are reported as `false`/`None` so the caller can tell the
// accepted path.

/// Slot order of [`SimUnit::larva_spawn_side_values`]: `[left, top, right,
/// bottom]`.  The four 16-bit spawn scores the retail record keeps after
/// `CUnit+0xd0` are addressed in this order (`+0xd0` left, `+0xd2` top,
/// `+0xd4` right, `+0xd6` bottom).
const A39_SIDE_LEFT: usize = 0;
const A39_SIDE_RIGHT: usize = 2;
const A39_SIDE_BOTTOM: usize = 3;

/// A spawn-side score saturates at 100 and every accepted placement adds 25.
const A39_SIDE_SCORE_CAP: i32 = 100;
const A39_SIDE_SCORE_STEP: i32 = 25;

impl SimUnit {
    /// `0x005e0250`: thunk onto the record accessor that returns the unit type
    /// id.  The retail body is a single tail jump into the `CUnit+0x64`
    /// getter, so the recovered behaviour is just the type id of the record.
    pub fn a39_record_type_id(&self) -> u16 {
        self.type_id
    }

    /// `0x005e0280`: record-handle comparison.  Retail compares the two
    /// supplied integers and returns 1 only when they are identical, so the
    /// modelled equivalent is "does this handle name this record".
    pub fn a39_id_matches(&self, id: u32) -> bool {
        self.id == id
    }

    /// `0x005e02c8`: a leaf predicate whose whole body is `return 1`.  It
    /// accepts every candidate; the spawn-side scan therefore relies on the
    /// remaining tests to reject a side.
    pub fn a39_accepts_any(&self) -> bool {
        true
    }

    /// `0x005e047f`: raise the **bottom** spawn-side score (`CUnit+0xd6`) by
    /// 25, saturating at 100.  Retail first requires `index > bound` and
    /// aborts otherwise; that guard is reported as `false`.  Returns true when
    /// the score changed.
    pub fn a39_raise_bottom_side_score(&mut self, index: usize, bound: usize) -> bool {
        if index <= bound {
            return false;
        }
        Self::a39_bump_side_score(&mut self.larva_spawn_side_values, A39_SIDE_BOTTOM)
    }

    /// `0x005e04ad`: `index < bound` selects the **left** side score
    /// (`CUnit+0xd0`), otherwise the **right** side (`CUnit+0xd4`); the chosen
    /// score is raised by 25 up to 100.  Returns the side that changed, or
    /// `None` when it was already capped.
    pub fn a39_raise_side_score_for_index(&mut self, index: usize, bound: usize) -> Option<usize> {
        let side = if index < bound {
            A39_SIDE_LEFT
        } else {
            A39_SIDE_RIGHT
        };
        Self::a39_bump_side_score(&mut self.larva_spawn_side_values, side).then_some(side)
    }

    fn a39_bump_side_score(scores: &mut [i32; 4], side: usize) -> bool {
        let score = &mut scores[side];
        if *score >= A39_SIDE_SCORE_CAP {
            return false;
        }
        *score = (*score + A39_SIDE_SCORE_STEP).min(A39_SIDE_SCORE_CAP);
        true
    }

    /// `0x005e08e0`: the "keep the better candidate" rule of the spawn
    /// selection loop.  The retail body compares the **second** word of the
    /// candidate pair first (`<=`), then the **first** word (`<`), so an equal
    /// pair keeps the incumbent.  Modelled as the pure pair fold the scan
    /// performs.
    pub fn a39_keep_smaller_pair(
        &self,
        incumbent: (u32, u32),
        candidate: (u32, u32),
    ) -> (u32, u32) {
        if candidate.1 <= incumbent.1 && (candidate.1 < incumbent.1 || candidate.0 < incumbent.0) {
            candidate
        } else {
            incumbent
        }
    }

    /// `0x005e08fa`: the single-key variant of the same fold.  Retail replaces
    /// the incumbent when the candidate's first word is strictly smaller and
    /// copies both words across.
    pub fn a39_keep_lower_first(&self, incumbent: (u32, u32), candidate: (u32, u32)) -> (u32, u32) {
        if candidate.0 < incumbent.0 {
            candidate
        } else {
            incumbent
        }
    }

    /// `0x005e0be7`: one step of the scenario clock builder.  Given the
    /// countdown length in seconds (`esi` in retail) and the elapsed seconds,
    /// retail stores, in this order:
    ///
    /// 1. `limit - elapsed` — seconds still on the clock,
    /// 2. `(elapsed + 5) / 60` — elapsed minutes, rounded up on five seconds,
    /// 3. `elapsed % 60` — the elapsed second inside the minute,
    /// 4. `(limit / 60) - ((elapsed + 5) / 60)` — minutes still on the clock,
    /// 5. `(limit - elapsed) % 60` — the remaining second inside the minute.
    ///
    /// C truncation is reproduced with `i32` arithmetic (Rust divides and
    /// takes remainders the same way).
    pub fn a39_clock_parts(&self, limit_seconds: i32, elapsed_seconds: i32) -> [i32; 5] {
        let minutes_elapsed = (elapsed_seconds + 5) / 0x3c;
        [
            limit_seconds - elapsed_seconds,
            minutes_elapsed,
            elapsed_seconds % 0x3c,
            limit_seconds / 0x3c - minutes_elapsed,
            (limit_seconds - elapsed_seconds) % 0x3c,
        ]
    }

    /// `0x005e0b61`: the same clock builder with the countdown length fixed at
    /// `0xb4` (180 seconds, three minutes).  Retail writes the remaining
    /// seconds, the rounded elapsed minutes, the elapsed second, `3 -` the
    /// rounded minutes and `(0xb4 - elapsed) % 60`.
    pub fn a39_three_minute_clock(&self, elapsed_seconds: i32) -> [i32; 5] {
        self.a39_clock_parts(0xb4, elapsed_seconds)
    }

    /// `0x005e0a39`: the formatted-entry version of `0x005e0b61`.  Before
    /// recomputing the three-minute clock retail clears the destination text
    /// buffer (it zeroes the payload, writes the size 0 and restores the
    /// 16-byte small-string capacity), then runs the same arithmetic.  The
    /// buffer reset is modelled by clearing `text`; the values handed to the
    /// text formatter are returned.
    pub fn a39_refresh_three_minute_clock(
        &self,
        elapsed_seconds: i32,
        text: &mut String,
    ) -> [i32; 5] {
        text.clear();
        self.a39_three_minute_clock(elapsed_seconds)
    }
}

impl World {
    /// `0x005e134a`: the hit test that gates drawing the 460x35 dialog at
    /// `(0, 5)`.  Retail accepts when `y <= bottom` and either `y < bottom` or
    /// `x <= right`, i.e. the bottom edge is inclusive and the x check only
    /// applies on that edge.  The dialog command itself (command `0x1d` with
    /// the `(0, 5, 460, 35)` rectangle) is presentation and carries no
    /// simulation state, so only the recovered predicate is reproduced.
    pub fn a39_dialog_hit_test(&self, x: i32, y: i32, right: i32, bottom: i32) -> bool {
        y <= bottom && (y < bottom || x <= right)
    }
}

#[cfg(test)]
mod tests_agent39 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    /// `0x005e0250`, `0x005e0280` and `0x005e02c8`: the record accessors
    /// report the unit's own type and handle and accept every candidate.
    #[test]
    fn record_accessors_read_their_own_record() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 10, 10).unwrap();
        let u = &w.units[marine];
        assert_eq!(u.a39_record_type_id(), uid::MARINE);
        assert!(u.a39_id_matches(u.id));
        assert!(!u.a39_id_matches(u.id.wrapping_add(1)));
        assert!(u.a39_accepts_any());
    }

    /// `0x005e047f`: the bottom score gains 25 per accepted placement, stops
    /// at 100, and the `index > bound` guard rejects the other branch.
    #[test]
    fn bottom_side_score_ramps_by_25_to_the_cap() {
        let mut w = world();
        let hatch = w.spawn(0, uid::HATCHERY, 8, 8).unwrap();
        let unit = &mut w.units[hatch];
        unit.larva_spawn_side_values = [0, 0, 0, 90];

        assert!(unit.a39_raise_bottom_side_score(4, 3));
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_BOTTOM], 100);

        // Already at the cap: no change.
        assert!(!unit.a39_raise_bottom_side_score(4, 3));
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_BOTTOM], 100);

        // Guard: the index must be strictly greater than the bound.
        unit.larva_spawn_side_values[A39_SIDE_BOTTOM] = 10;
        assert!(!unit.a39_raise_bottom_side_score(3, 3));
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_BOTTOM], 10);

        // A step below the cap adds exactly 25.
        assert!(unit.a39_raise_bottom_side_score(5, 3));
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_BOTTOM], 35);
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_LEFT], 0);
    }

    /// `0x005e04ad`: the index/bound comparison picks the left score below the
    /// bound and the right score at or above it.
    #[test]
    fn index_selects_left_or_right_side_score() {
        let mut w = world();
        let hatch = w.spawn(0, uid::HATCHERY, 20, 20).unwrap();
        let unit = &mut w.units[hatch];
        unit.larva_spawn_side_values = [0, 0, 0, 0];

        assert_eq!(
            unit.a39_raise_side_score_for_index(0, 2),
            Some(A39_SIDE_LEFT)
        );
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_LEFT], 25);
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_RIGHT], 0);

        assert_eq!(
            unit.a39_raise_side_score_for_index(2, 2),
            Some(A39_SIDE_RIGHT)
        );
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_RIGHT], 25);
        assert_eq!(
            unit.a39_raise_side_score_for_index(9, 2),
            Some(A39_SIDE_RIGHT)
        );
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_RIGHT], 50);

        unit.larva_spawn_side_values[A39_SIDE_LEFT] = 100;
        assert_eq!(unit.a39_raise_side_score_for_index(1, 2), None);
        assert_eq!(unit.larva_spawn_side_values[A39_SIDE_LEFT], 100);
    }

    /// `0x005e08e0` and `0x005e08fa`: the two "keep the better candidate"
    /// folds used by the spawn-side scan.
    #[test]
    fn pair_folds_keep_the_smaller_candidate() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 12, 12).unwrap();
        let u = &w.units[marine];

        // Second word first, then the first word as tie-break.
        let best = (7, 40);
        assert_eq!(u.a39_keep_smaller_pair(best, (9, 39)), (9, 39));
        assert_eq!(u.a39_keep_smaller_pair(best, (5, 40)), (5, 40));
        assert_eq!(u.a39_keep_smaller_pair(best, (8, 40)), best);
        assert_eq!(u.a39_keep_smaller_pair(best, (1, 41)), best);

        // Single key: only a strictly smaller first word replaces.
        assert_eq!(u.a39_keep_lower_first(best, (6, 99)), (6, 99));
        assert_eq!(u.a39_keep_lower_first(best, (7, 1)), best);
        assert_eq!(u.a39_keep_lower_first(best, (8, 0)), best);
    }

    /// `0x005e0be7`: the five clock values for a caller-supplied countdown.
    #[test]
    fn clock_parts_split_elapsed_and_remaining() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 14, 14).unwrap();
        let u = &w.units[marine];

        assert_eq!(u.a39_clock_parts(180, 0), [180, 0, 0, 3, 0]);
        assert_eq!(u.a39_clock_parts(180, 59), [121, 1, 59, 2, 1]);
        // The five-second rounding is what pushes the minute over.
        assert_eq!(u.a39_clock_parts(180, 55), [125, 1, 55, 2, 5]);
        assert_eq!(u.a39_clock_parts(180, 180), [0, 3, 0, 0, 0]);
        // C remainder truncates toward zero, so an over-run past the limit
        // stays negative rather than wrapping into the previous minute.
        assert_eq!(u.a39_clock_parts(600, 601), [-1, 10, 1, 0, -1]);
    }

    /// `0x005e0b61`: the same builder with the three-minute limit hard-coded.
    #[test]
    fn three_minute_clock_matches_the_180_second_limit() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 16, 16).unwrap();
        let u = &w.units[marine];

        assert_eq!(u.a39_three_minute_clock(0), [180, 0, 0, 3, 0]);
        assert_eq!(u.a39_three_minute_clock(175), [5, 3, 55, 0, 5]);
        assert_eq!(u.a39_three_minute_clock(90), [90, 1, 30, 2, 30]);
        assert_eq!(u.a39_three_minute_clock(180), u.a39_clock_parts(180, 180));
    }

    /// `0x005e0a39`: the formatted entry clears the destination text before
    /// recomputing the three-minute values.
    #[test]
    fn refresh_clears_the_display_before_filling() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 18, 18).unwrap();
        let u = &w.units[marine];
        let mut text = String::from("stale countdown");

        let parts = u.a39_refresh_three_minute_clock(175, &mut text);
        assert!(text.is_empty());
        assert_eq!(parts, [5, 3, 55, 0, 5]);
        assert_eq!(parts, u.a39_three_minute_clock(175));
    }

    /// `0x005e134a`: the bottom edge of the dialog rectangle is inclusive and
    /// the x bound only applies on that edge.
    #[test]
    fn dialog_hit_test_includes_the_boundary() {
        let w = world();

        assert!(w.a39_dialog_hit_test(10, 5, 460, 35));
        assert!(w.a39_dialog_hit_test(500, 34, 460, 35));
        assert!(w.a39_dialog_hit_test(460, 35, 460, 35));
        assert!(!w.a39_dialog_hit_test(461, 35, 460, 35));
        assert!(!w.a39_dialog_hit_test(10, 36, 460, 35));
    }
}

// ===========================================================================
// Merged from src/translated/agent05.rs
// ===========================================================================
// Translation batch 05.  Only this file is edited by the batch.
//
// Nine `decompiled_uncited` routines from the `0x005b5000..=0x005b6fff`
// slice of the retail `CUnit` method table.  Every item names the exact
// retail address it was recovered from.
//
// The routines in this slice are mostly tiny `CUnit` accessors.  The port
// does not keep a `CSprite`, a raw `CUnit+0xdc` status word, a raw
// `CUnit+0x70/0xc0/0xd0/0xfc` link, or the global sound mixer, so the
// accessors that only poke those unmodelled slots are listed as skipped in
// the batch report rather than approximated here.

impl SimUnit {
    /// `0x005b5640`: true when the recovered status count is positive.
    ///
    /// Retail builds the count from three inputs: `CUnit+0x115` (the Stim
    /// Pack timer, +1), `CUnit+0xdc` bit 28 (+1) and `CUnit+0x116` (the
    /// Ensnare timer, -1), then returns `count > 0`.  This engine keeps the
    /// two timers but not bit 28 -- the same simplification already used by
    /// `World::modified_speed` for the twin routine `FUN_005b6900` -- so a
    /// positive count is "stimmed and not ensnared".
    pub fn a05_status_boost_active(&self) -> bool {
        self.a05_status_modifier() > 0
    }

    /// `0x005b68b0`: apply the recovered attack-damage scaling.
    ///
    /// The routine is `FUN_005b6900` with damage instead of speed: a positive
    /// status count doubles the value, a negative count returns
    /// `value - value/4`, and a zero count leaves it unchanged.  The count
    /// is built exactly as in [`SimUnit::a05_status_boost_active`] (Stim
    /// `CUnit+0x115` +1, Ensnare `CUnit+0x116` -1, `CUnit+0xdc` bit 28 is
    /// not retained).
    pub fn a05_status_damage_scale(&self, value: u32) -> u32 {
        let count = self.a05_status_modifier();
        if count > 0 {
            value.wrapping_mul(2)
        } else if count < 0 {
            value - (value >> 2)
        } else {
            value
        }
    }

    /// Shared status count for `0x005b5640` and `0x005b68b0` (and the speed
    /// routine `FUN_005b6900`): `+1` for Stim Pack, `-1` for Ensnare.
    fn a05_status_modifier(&self) -> i32 {
        let mut count = 0;
        if self.status.stim_ticks > 0 {
            count += 1;
        }
        if self.status.ensnare_ticks > 0 {
            count -= 1;
        }
        count
    }

    /// `0x005b5920`: `CUnit+0xdc` bit 11 set while status bit 4 (the
    /// completed flag, see `FUN_005b5840`) is clear.
    ///
    /// Bit 4 is [`SimUnit::completed`].  Bit 11 is not retained by this
    /// engine, so it is supplied by the caller.
    pub fn a05_bit11_set_and_unfinished(&self, bit_11: bool) -> bool {
        bit_11 && !self.completed
    }

    /// `0x005b61ca`: empty virtual slot.  The recovered body is a bare
    /// `return`; the method exists so vtable dispatch still resolves.
    pub fn a05_noop(&self) {}

    /// `0x005b62f0`: true when the queued row in a Zerg queue slot is below
    /// `0x6a`, i.e. it is a mobile unit rather than a building (row `0x6a`
    /// is the Command Center, the first building row).
    ///
    /// The slot lookup is `FUN_0058deb0`, which reads the ring of five u16
    /// type ids at `CUnit+0x98`, indexed by `(CUnit+0xa4 + slot) % 5`.  This
    /// engine's Zerg queue is [`SimUnit::production`], whose front is the
    /// head slot, so `slot` indexes it from the front.
    pub fn a05_queue_slot_below_buildings(&self, slot: u8) -> bool {
        self.a05_queue_slot_type(slot) < 0x6a
    }

    /// `FUN_0058deb0`: type id stored in the Zerg five-slot queue
    /// (`CUnit+0x98`), or zero for an empty/non-training slot.
    fn a05_queue_slot_type(&self, slot: u8) -> u16 {
        match self.production.get(slot as usize) {
            Some(Order::Train { unit_type }) => *unit_type,
            _ => 0,
        }
    }

    /// `0x005b63bd`: raw `CUnit*` identity test (`this == other`).  Retail
    /// compares the two `this` pointers, so two distinct units are never
    /// equal even when their fields coincide.
    pub fn a05_is_same_unit(&self, other: &SimUnit) -> bool {
        std::ptr::eq(self, other)
    }

    /// `0x005b66f0`: set `CUnit+0xdc` bit 26 (`0x04000000`), the capability
    /// bit retained only for types with `units.dat` flag `0x20000000`
    /// (cleared again by `FUN_005b66c0`).
    pub fn a05_set_flag_26(&mut self) {
        self.flag_26 = true;
    }

    /// `0x005b6890`: play fixed line `0xf` for the unit's owner
    /// (`FUN_00773180(CUnit+0x4c, 0xf)`).
    ///
    /// `FUN_00773180` resolves a per-player sound-table entry; this engine
    /// has no global mixer, so the request is returned as
    /// `(owner, sound id)` for the caller to forward.
    pub fn a05_alert_sound(&self) -> (u8, u8) {
        (self.owner, 0x0f)
    }

    /// `0x005b6af0`: play the caller's sound id for the unit's owner
    /// (`FUN_00773180(CUnit+0x4c, sound)`).  Like [`SimUnit::a05_alert_sound`]
    /// the request is returned rather than played.
    pub fn a05_owner_sound(&self, sound: u8) -> (u8, u8) {
        (self.owner, sound)
    }
}

#[cfg(test)]
mod tests_agent05 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::World;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    #[test]
    fn status_boost_and_damage_scale_follow_the_recovered_counts() {
        // 0x005b5640 / 0x005b68b0: +1 for Stim (CUnit+0x115), -1 for
        // Ensnare (CUnit+0x116), damage doubled when positive and reduced
        // by a quarter when negative.
        let mut w = world();
        let m = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        assert!(!w.units[m].a05_status_boost_active());
        assert_eq!(w.units[m].a05_status_damage_scale(100), 100);

        w.units[m].status.stim_ticks = 5;
        assert!(w.units[m].a05_status_boost_active());
        assert_eq!(w.units[m].a05_status_damage_scale(100), 200);

        w.units[m].status.ensnare_ticks = 5;
        assert!(!w.units[m].a05_status_boost_active(), "the counts cancel");
        assert_eq!(w.units[m].a05_status_damage_scale(100), 100);

        w.units[m].status.stim_ticks = 0;
        assert!(!w.units[m].a05_status_boost_active());
        assert_eq!(w.units[m].a05_status_damage_scale(100), 75);
        assert_eq!(w.units[m].a05_status_damage_scale(101), 76);
    }

    #[test]
    fn bit11_and_unfinished_needs_both_inputs() {
        // 0x005b5920: bit 11 set at CUnit+0xdc while bit 4 (completed) is
        // clear.  Bit 4 maps to SimUnit::completed.
        let mut w = world();
        let m = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        assert!(!w.units[m].a05_bit11_set_and_unfinished(false));
        assert!(!w.units[m].a05_bit11_set_and_unfinished(true));
        w.units[m].completed = false;
        assert!(w.units[m].a05_bit11_set_and_unfinished(true));
        assert!(!w.units[m].a05_bit11_set_and_unfinished(false));
    }

    #[test]
    fn empty_virtual_slot_does_nothing() {
        // 0x005b61ca: the recovered body is an empty return.
        let mut w = world();
        let m = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        let before = (
            w.units[m].x,
            w.units[m].y,
            w.units[m].hp,
            w.units[m].order_row,
        );
        w.units[m].a05_noop();
        assert_eq!(
            (
                w.units[m].x,
                w.units[m].y,
                w.units[m].hp,
                w.units[m].order_row
            ),
            before
        );
    }

    #[test]
    fn queue_slot_predicate_reads_production_rows() {
        // 0x005b62f0 with the FUN_0058deb0 slot lookup: rows below the
        // building range 0x6a are mobile units.
        let mut w = world();
        let h = w.spawn(0, uid::HATCHERY, 200, 200).unwrap();
        assert!(w.units[h].a05_queue_slot_below_buildings(0), "empty slot");
        w.units[h].production.push_back(Order::Train {
            unit_type: uid::ZERGLING,
        });
        w.units[h].production.push_back(Order::Train {
            unit_type: uid::COMMAND_CENTER,
        });
        assert_eq!(w.units[h].a05_queue_slot_type(0), uid::ZERGLING);
        assert!(w.units[h].a05_queue_slot_below_buildings(0));
        assert!(!w.units[h].a05_queue_slot_below_buildings(1));
        assert_eq!(w.units[h].a05_queue_slot_type(1), uid::COMMAND_CENTER);
        assert!(
            w.units[h].a05_queue_slot_below_buildings(2),
            "past the queue"
        );
    }

    #[test]
    fn identity_test_matches_the_this_pointer() {
        // 0x005b63bd: `this == other` on the CUnit pointer.
        let mut w = world();
        let a = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        let b = w.spawn(0, uid::MARINE, 120, 100).unwrap();
        let same = w.units[a].clone();
        assert!(w.units[a].a05_is_same_unit(&w.units[a]));
        assert!(!w.units[a].a05_is_same_unit(&w.units[b]));
        assert!(!w.units[a].a05_is_same_unit(&same), "a clone is not this");
    }

    #[test]
    fn flag_26_setter_sets_the_status_bit() {
        // 0x005b66f0: OR 0x04000000 into CUnit+0xdc.
        let mut w = world();
        let m = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        assert!(!w.units[m].flag_26);
        w.units[m].a05_set_flag_26();
        assert!(w.units[m].flag_26);
        w.units[m].a05_set_flag_26();
        assert!(w.units[m].flag_26, "idempotent");
    }

    #[test]
    fn sound_requests_carry_the_owner_and_the_recovered_id() {
        // 0x005b6890: FUN_00773180(CUnit+0x4c, 0xf).
        // 0x005b6af0: FUN_00773180(CUnit+0x4c, sound).
        let mut w = world();
        let m = w.spawn(0, uid::MARINE, 100, 100).unwrap();
        let e = w.spawn(1, uid::MARINE, 300, 100).unwrap();
        assert_eq!(w.units[m].a05_alert_sound(), (0, 0x0f));
        assert_eq!(w.units[e].a05_alert_sound(), (1, 0x0f));
        assert_eq!(w.units[m].a05_owner_sound(0x2a), (0, 0x2a));
        assert_eq!(w.units[e].a05_owner_sound(0x2a), (1, 0x2a));
    }
}

