// Translation batch 07.  Only this file is edited by the batch.
//
// The batch covers the `decompiled_uncited` rows in `0x005ba000..=0x005bffff`
// whose decompiled body is at most 100 bytes and whose observable state is
// already exposed by [`crate::sim::World`] / [`crate::sim::SimUnit`].  Most
// rows in that block are fragments of the retail unit-order switch (they read
// caller stack slots through `unaff_EBP`, or write the opaque order-descriptor
// pointer at `CUnit+0x100`); those are documented as skipped in the batch
// report instead of being guessed at.

/// `FUN_006c1ee0` half-extent used by the `0x005bac70` area callback: `0x30`
/// world pixels on each axis.
pub const A07_STASIS_HALF_EXTENT: i32 = 0x30;

/// `FUN_005bb640` stasis refresh timer applied by the `0x005bad20` callback.
pub const A07_STASIS_TICKS: i32 = crate::sim::STASIS_UPDATES;

impl World {
    /// `0x005ba160`: wrapper that calls `FUN_005ba190(1, ...)`.
    ///
    /// The kind-1 branch of `FUN_005ba190` calls `FUN_005b6c50(order_id, 0, 0)`
    /// and then `FUN_005b6cd0(order_id, 0, 0, 0xe4, 0)`, i.e. it issues an
    /// order row without a point.  The retail wrapper's third argument is the
    /// null-point sentinel (`FUN_005b6c50` aborts unless it is zero), so the
    /// Rust front door forwards `None`.  The preliminary race/queue checks and
    /// error sounds in `FUN_005ba190` are presentation checks with no state
    /// effect and are not modelled.
    pub fn a07_issue_order_without_point(
        &mut self,
        unit_id: u32,
        order_id: u8,
    ) -> Result<(), SimError> {
        self.issue_order_id(unit_id, order_id, None, None)
    }

    /// `0x005ba130`: wrapper that calls `FUN_005ba190(2, ...)`.
    ///
    /// The kind-2 branch of `FUN_005ba190` calls
    /// `FUN_005b6cd0(order_id, point(x, y), 0, flags, 0)`; the point is built
    /// from the wrapper's two coordinate words.  The `flags` word selects the
    /// retail order descriptor and has no Rust equivalent because
    /// [`World::issue_order_id`] derives the descriptor from `orders.dat`.
    /// The preliminary race/queue checks and error sounds are not modelled.
    pub fn a07_issue_order_at_point(
        &mut self,
        unit_id: u32,
        order_id: u8,
        pos: (i32, i32),
    ) -> Result<(), SimError> {
        self.issue_order_id(unit_id, order_id, None, Some(pos))
    }

    /// `0x005bac70`: apply the stasis area effect at `pos`.
    ///
    /// Retail creates the effect object with `FUN_00588410(0x169, x, y, 0)`,
    /// marks the caster's order (`FUN_0058b430(0x11)`) and then asks the
    /// `FUN_005c9620` box enumerator `FUN_006c1ee0(x, y, 0x30, callback, ctx)`
    /// to visit every unit in the box.  The callback is [`Self::a07_area_stasis_accepts`],
    /// which applies the recovered `0x83` stasis timer through `FUN_005bb640`.
    /// Object creation, the order marker and the callback's return value are
    /// outside the Rust model; the returned ids are the units that received
    /// the timer.
    pub fn a07_area_stasis(&mut self, caster: u32, pos: (i32, i32)) -> Vec<u32> {
        let mut hit = Vec::new();
        for id in self.units_in_rect(pos, A07_STASIS_HALF_EXTENT) {
            if !self.a07_area_stasis_accepts(caster, id) {
                continue;
            }
            if let Some(i) = self.index_of(id) {
                self.units[i].status.apply_stasis(A07_STASIS_TICKS);
                hit.push(id);
            }
        }
        hit
    }

    /// `0x005bad20`: the `FUN_006c1ee0` box callback used by
    /// [`Self::a07_area_stasis`].
    ///
    /// The decompiled body returns immediately when the visited unit is the
    /// caster, then rejects the unit when any of the three predicates is
    /// nonzero:
    ///
    /// * `FUN_005b3ac0` — `CUnit+0xdc` bit 26 ([`SimUnit::flag_26`]);
    /// * `FUN_005b5820` — `units.dat` building flag (`CUnit+0x64 < 0xe4` and
    ///   flag 0x1), exposed as [`Self::unit_is_building_flagged`];
    /// * `FUN_005b5840` — `CUnit+0xdc` bit 4, exposed as
    ///   [`SimUnit::is_completed_flag`].
    ///
    /// Survival is added because the enumerator behind `FUN_006c1ee0` only
    /// visits living units (`FUN_005c9620`, see [`Self::units_in_rect`]).
    pub fn a07_area_stasis_accepts(&self, caster: u32, target: u32) -> bool {
        let Some(unit) = self.unit(target) else {
            return false;
        };
        unit.alive
            && unit.id != caster
            && !unit.flag_26()
            && !self.unit_is_building_flagged(unit.type_id)
            && !unit.is_completed_flag()
    }

    /// `0x005bacff`: apply the `0x16` Maelstrom timer when the unit's
    /// `units.dat` type is organic.
    ///
    /// The body increments a module counter, calls `FUN_005b5c20` (organic
    /// flag 0x10000, [`crate::data::UnitType::is_organic`]) and on a nonzero
    /// result calls `FUN_005d2a80(0x16)`, the Maelstrom refresh.  The counter
    /// has no recovered reader and is omitted; the retail function returns
    /// zero unconditionally, while the returned `bool` here reports whether
    /// the organic branch applied the timer.
    pub fn a07_maelstrom_if_organic(&mut self, unit_id: u32) -> bool {
        let Some(i) = self.index_of(unit_id) else {
            return false;
        };
        if !self.data.unit(self.units[i].type_id).is_organic() {
            return false;
        }
        self.units[i]
            .status
            .apply_maelstrom(crate::sim::MAELSTROM_UPDATES);
        true
    }

    /// `0x005bb6a0`: clear the `CUnit+0x119` stasis timer, verify that the
    /// unit still carries another disabling flag, then clear the unsupported
    /// status bit 26.
    ///
    /// The body writes `CUnit+0x119 = 0`, calls `FUN_005b5aa0` (true when
    /// `CUnit+0xdc` bit 10, or the `+0x117`/`+0x119`/`+0x124` timers are
    /// nonzero), aborts to the runtime error handler when nothing remains,
    /// calls `FUN_005b66c0` (clear flag 26 unless the type carries `units.dat`
    /// flag 0x20000000) and finally refreshes a HUD plate
    /// (`FUN_005cbe10(0x16d, 0x16f)`).  The HUD refresh is not modelled; a
    /// `false` return is the recovered error path instead of terminating.
    pub fn a07_end_stasis(&mut self, unit_id: u32) -> bool {
        let Some(i) = self.index_of(unit_id) else {
            return false;
        };
        self.units[i].status.clear_stasis();
        let unit = &self.units[i];
        let still_disabled = unit.flag_10
            || unit.status.lockdown_ticks != 0
            || unit.status.stasis_ticks != 0
            || unit.status.maelstrom_ticks != 0;
        if !still_disabled {
            return false;
        }
        self.clear_unsupported_flag_26(i);
        true
    }

    /// `0x005bf9b0`: pick one element from a temporary list.
    ///
    /// The retail body takes the list length (`FUN_0075d720`), copies the
    /// list (`FUN_0075d6e0`), draws an inclusive index with
    /// `FUN_007415f0(0, len - 1, 0x32)` and returns `list[index]`
    /// (`FUN_0075d660`).  The inclusive draw is replaced by the crate's deterministic LCG ([`World::world_rand`]) so replays stay
    /// reproducible.  An empty list yields `None`; the retail routine would
    /// index `-1` and fault.
    pub fn a07_rand_pick<T: Copy>(&mut self, items: &[T]) -> Option<T> {
        if items.is_empty() {
            return None;
        }
        let index = self.world_rand() as usize % items.len();
        Some(items[index])
    }
}

impl SimUnit {
    /// `0x005bf210`: release the `CUnit+0x100` slot.
    ///
    /// When `FUN_005bb920` reports the slot nonzero, retail calls
    /// `FUN_0076bd90(slot)` (release the linked object) and writes zero to
    /// `CUnit+0x100`.  The release call is outside the Rust model, whose slot
    /// is the opaque [`SimUnit::field_100`] id; the observable write is
    /// reproduced here.  Returns whether a live slot was cleared.
    pub fn a07_release_field_100(&mut self) -> bool {
        if !self.field_100_nonzero() {
            return false;
        }
        self.set_field_100(0);
        true
    }

    /// `0x005bf8ca`: true when the unit's facing, snapped down to the start
    /// of its 64-step quadrant, is more than `0x40` angular steps away from
    /// `other_facing`.
    ///
    /// The body reads the facing byte at `CUnit+0x23` and snaps it with
    /// `0x20`/`0x60`/`0xa0`/`0xe0` boundaries to `0`/`0x40`/`0x80`/`0xc0`
    /// (back to `0` at and above `0xe0`).  `FUN_00569170` then returns the
    /// circular distance `min(d, 0x100 - d)`, and the predicate is
    /// `distance > 0x40`.
    pub fn a07_facing_quadrant_distant(&self, other_facing: u8) -> bool {
        let snapped = if self.facing < 0x20 {
            0
        } else if self.facing < 0x60 {
            0x40
        } else if self.facing < 0xa0 {
            0x80
        } else if self.facing < 0xe0 {
            0xc0
        } else {
            0
        };
        a07_facing_distance(snapped, other_facing) > 0x40
    }
}

/// `0x005bb721`: compare a 32-bit value's low byte against `expected`.
///
/// The decompiled body is `(unaff_EBX & 0xff) == in_EAX`; the function is a
/// leaf predicate with no unit access, so it is kept as a free helper.
pub fn a07_low_byte_matches(value: u32, expected: u32) -> bool {
    value & 0xff == expected
}

/// `FUN_00569170` as used by `0x005bf8ca`: circular 8-bit angular distance.
fn a07_facing_distance(a: u8, b: u8) -> u8 {
    let d = b.wrapping_sub(a);
    if d < 0x81 { d } else { 0u8.wrapping_sub(d) }
}

#[cfg(test)]
mod tests_agent07 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use crate::sim::{MAELSTROM_UPDATES, Order, STASIS_UPDATES};
    use std::sync::Arc;

    fn open_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    #[test]
    fn wrapper_005ba130_issues_the_order_at_the_given_point() {
        let mut w = open_world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let id = w.units[marine].id;

        w.a07_issue_order_at_point(id, 6, (400, 400)).unwrap();

        assert_eq!(w.units[marine].order_row, 6);
        assert_eq!(w.units[marine].order, Order::Move { pos: (400, 400) });
    }

    #[test]
    fn wrapper_005ba160_issues_the_order_without_a_point() {
        let mut w = open_world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let id = w.units[marine].id;

        w.a07_issue_order_without_point(id, 1).unwrap();

        assert_eq!(w.units[marine].order_row, 1);
        assert!(matches!(
            w.units[marine].order,
            Order::HoldPosition | Order::Stop
        ));
    }

    #[test]
    fn area_stasis_005bac70_uses_the_callback_filters() {
        let mut w = open_world();
        let caster = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let caster_id = w.units[caster].id;

        let accepted = w.spawn(1, uid::ZERGLING, 330, 320).unwrap();
        w.units[accepted].completed = false;

        let completed = w.spawn(1, uid::ZERGLING, 340, 320).unwrap();
        assert!(w.units[completed].completed);

        let building = w.spawn(1, uid::HATCHERY, 350, 320).unwrap();
        w.units[building].completed = false;

        let flagged = w.spawn(1, uid::ZERGLING, 300, 320).unwrap();
        w.units[flagged].completed = false;
        w.units[flagged].flag_26 = true;

        let out_of_box = w.spawn(1, uid::ZERGLING, 500, 320).unwrap();
        w.units[out_of_box].completed = false;

        let hit = w.a07_area_stasis(caster_id, (330, 320));

        assert_eq!(hit, vec![w.units[accepted].id]);
        assert_eq!(w.units[accepted].status.stasis_ticks, STASIS_UPDATES);
        assert_eq!(w.units[completed].status.stasis_ticks, 0);
        assert_eq!(w.units[building].status.stasis_ticks, 0);
        assert_eq!(w.units[flagged].status.stasis_ticks, 0);
        assert_eq!(w.units[out_of_box].status.stasis_ticks, 0);
        assert_eq!(w.units[caster].status.stasis_ticks, 0);
    }

    #[test]
    fn callback_005bad20_rejects_the_caster_buildings_and_flag_26() {
        let mut w = open_world();
        let caster = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let caster_id = w.units[caster].id;
        let zergling = w.spawn(1, uid::ZERGLING, 330, 320).unwrap();
        let zergling_id = w.units[zergling].id;
        w.units[zergling].completed = false;

        assert!(!w.a07_area_stasis_accepts(caster_id, caster_id));
        assert!(w.a07_area_stasis_accepts(caster_id, zergling_id));

        w.units[zergling].flag_26 = true;
        assert!(!w.a07_area_stasis_accepts(caster_id, zergling_id));

        w.units[zergling].flag_26 = false;
        w.units[zergling].completed = true;
        assert!(!w.a07_area_stasis_accepts(caster_id, zergling_id));

        let building = w.spawn(1, uid::HATCHERY, 350, 320).unwrap();
        let building_id = w.units[building].id;
        w.units[building].completed = false;
        assert!(!w.a07_area_stasis_accepts(caster_id, building_id));

        assert!(!w.a07_area_stasis_accepts(caster_id, 0xdead_beef));
    }

    #[test]
    fn maelstrom_005bacff_only_applies_to_organic_types() {
        let mut w = open_world();
        let zergling = w.spawn(0, uid::ZERGLING, 320, 320).unwrap();
        let goliath = w.spawn(0, uid::GOLIATH, 340, 320).unwrap();

        assert!(w.a07_maelstrom_if_organic(w.units[zergling].id));
        assert_eq!(w.units[zergling].status.maelstrom_ticks, MAELSTROM_UPDATES);

        assert!(!w.a07_maelstrom_if_organic(w.units[goliath].id));
        assert_eq!(w.units[goliath].status.maelstrom_ticks, 0);

        assert!(!w.a07_maelstrom_if_organic(0xdead_beef));
    }

    #[test]
    fn end_stasis_005bb6a0_needs_another_disabling_flag() {
        let mut w = open_world();
        let zergling = w.spawn(0, uid::ZERGLING, 320, 320).unwrap();
        let id = w.units[zergling].id;
        w.units[zergling].flag_26 = true;
        w.units[zergling].status.apply_stasis(STASIS_UPDATES);

        // Only stasis is active: retail takes the runtime-error path and does
        // not reach FUN_005b66c0, so flag 26 must survive.
        assert!(!w.a07_end_stasis(id));
        assert_eq!(w.units[zergling].status.stasis_ticks, 0);
        assert!(w.units[zergling].flag_26);

        w.units[zergling].flag_26 = true;
        w.units[zergling].status.apply_stasis(STASIS_UPDATES);
        w.units[zergling].status.apply_lockdown(3);

        assert!(w.a07_end_stasis(id));
        assert_eq!(w.units[zergling].status.stasis_ticks, 0);
        assert_eq!(w.units[zergling].status.lockdown_ticks, 3);
        assert!(!w.units[zergling].flag_26);

        assert!(!w.a07_end_stasis(0xdead_beef));
    }

    #[test]
    fn low_byte_predicate_005bb721_matches_the_decompiled_compare() {
        assert!(a07_low_byte_matches(0x1234_56ff, 0xff));
        assert!(a07_low_byte_matches(0x00, 0));
        assert!(a07_low_byte_matches(0x100, 0));
        assert!(!a07_low_byte_matches(0x100, 0x100));
        assert!(!a07_low_byte_matches(0xfe, 0xff));
    }

    #[test]
    fn release_field_100_005bf210_clears_a_live_slot() {
        let mut w = open_world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let unit = &mut w.units[marine];

        assert!(!unit.a07_release_field_100());
        unit.set_field_100(0x1234);
        assert!(unit.a07_release_field_100());
        assert_eq!(unit.field_100(), 0);
        assert!(!unit.a07_release_field_100());
    }

    #[test]
    fn facing_quadrant_005bf8ca_uses_snapped_quadrant_starts() {
        let mut w = open_world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let unit = &mut w.units[marine];

        unit.facing = 0x10; // snaps to 0x00
        assert!(unit.a07_facing_quadrant_distant(0x50)); // 0x50 = 80 > 64
        assert!(!unit.a07_facing_quadrant_distant(0x30)); // 0x30 = 48
        assert!(!unit.a07_facing_quadrant_distant(0x40)); // 64 is not > 64

        unit.facing = 0x90; // snaps to 0x80
        assert!(unit.a07_facing_quadrant_distant(0x10)); // 112
        assert!(!unit.a07_facing_quadrant_distant(0xb0)); // 48

        unit.facing = 0xe5; // snaps back to 0x00
        assert!(!unit.a07_facing_quadrant_distant(0xff)); // 1
        assert!(unit.a07_facing_quadrant_distant(0x80)); // 128

        // Exhaustive: the helper always stays in 0..=0x80.
        for a in 0..=255u8 {
            for b in 0..=255u8 {
                assert!(a07_facing_distance(a, b) <= 0x80);
            }
        }
    }

    #[test]
    fn rand_pick_005bf9b0_is_in_bounds_and_deterministic() {
        let mut w = open_world();
        assert_eq!(w.a07_rand_pick::<u8>(&[]), None);
        assert_eq!(w.a07_rand_pick(&[7u8]), Some(7));

        let items = [10u8, 20, 30, 40];
        let mut seen = [false; 4];
        for _ in 0..64 {
            let picked = w.a07_rand_pick(&items).expect("non-empty list");
            let pos = items.iter().position(|v| *v == picked).unwrap();
            seen[pos] = true;
        }
        assert!(seen.iter().all(|v| *v), "every element should be reachable");

        let mut a = open_world();
        let mut b = open_world();
        for _ in 0..8 {
            assert_eq!(a.a07_rand_pick(&items), b.a07_rand_pick(&items));
        }
    }
}

// ===========================================================================
// Merged from src/translated/agent09.rs
// ===========================================================================
// Translation batch 09.  Only this file is edited by the batch.
//
// Ten `decompiled_uncited` routines from `0x005c8000..=0x005cffff`.  Every
// item below names its exact decompiled address.  Helper routines whose
// meaning was already recovered in `sim.rs` are called instead of being
// re-derived: `FUN_005b5820` (building flag), `FUN_005b4b70` (`CUnit+0x123`),
// `FUN_005b4bc0` (`CUnit+0x121`), `FUN_005b6630` (Maelstrom timer),
// `FUN_005b6b20` (energy flag), `FUN_005b5d30` (hero flag), `FUN_005b4aa0`
// (HP + shields in whole points), `FUN_005b4a20` (`CUnit+0x60 >> 8`),
// `FUN_005b5890` (Carrier/Reaver family) and `FUN_005692b0` (byte facing).

impl World {
    /// `0x005c8300`: target-value gate.  The retail routine first calls the
    /// `FUN_005c8ad0` assertion helper, which only returns on the normal path
    /// when the two units are on the same side (every other path is fatal),
    /// so the alliance check is modelled as the `allied` precondition.
    ///
    /// It then returns false for buildings (`FUN_005b5820`) and for units with
    /// a non-empty `CUnit+0x123` mask (`FUN_005b4b70`).  Otherwise it asks
    /// `FUN_005b5a50` whether the unit is a detector; a non-detector whose
    /// whole-point HP plus shields (`FUN_005b4aa0`) is below `0x51` (81) fails
    /// the gate, everything else passes.  The data-table detector bit is
    /// [`crate::data::UnitType::is_detector`].
    pub fn a09_value_target_gate(&self, i: usize, allied: bool) -> bool {
        if !allied {
            return false;
        }
        let u = &self.units[i];
        if self.unit_is_building_flagged(u.type_id) || u.mask_123() != 0 {
            return false;
        }
        let detector = self.data.unit(u.type_id).is_detector();
        detector || self.unit_current_total_points(i) >= 0x51
    }

    /// `0x005c88f0`: whether a caster's energy covers the target's whole-point
    /// HP plus shields, the low-health recharge/heal pre-check.
    ///
    /// `FUN_005c8ad0` is the same-side assertion as in
    /// [`World::a09_value_target_gate`] (modelled by `allied`).  The routine
    /// then requires the energy flag (`FUN_005b6b20`), the clear state of
    /// `CUnit+0xdc` bit 1 (`FUN_005b5810`, not separately modelled here and
    /// passed as `status_bit1`) and a non-hero row (`FUN_005b5d30`).  Finally
    /// the whole-point target total (`FUN_005b4aa0`) is compared with the low
    /// byte of `CUnit+0xa3`, i.e. the fixed-point energy `>> 8`
    /// (`FUN_005b4af0`).
    pub fn a09_energy_covers_heal(&self, i: usize, allied: bool, status_bit1: bool) -> bool {
        if !allied || status_bit1 {
            return false;
        }
        if !self.unit_has_energy(i) {
            return false;
        }
        let u = &self.units[i];
        if self.data.unit(u.type_id).is_hero() {
            return false;
        }
        let energy_whole = (u.energy_fixed() >> 8) & 0xff;
        self.unit_current_total_points(i) <= energy_whole
    }

    /// `0x005c8950`: true when `i` and the unit owned by `other_owner` share
    /// an owner, `i` carries an order unit target in `CUnit+0x5c`
    /// ([`SimUnit::order_unit_target`]), `i` is a hangar-family carrier or
    /// reaver (`FUN_005b5890`) and its whole-point HP (`FUN_005b4a20`,
    /// `CUnit+0x60 >> 8`) is below 11.
    pub fn a09_carrier_has_low_hp_target(&self, i: usize, other_owner: u8) -> bool {
        let u = &self.units[i];
        u.owner == other_owner
            && u.order_unit_target().is_some()
            && is_carrier_reaver_family(u.type_id)
            && (u.hp >> 8) < 0xb
    }
}

impl SimUnit {
    /// `0x005c8620`: recharge/recast status gate.  False when the owners in
    /// `CUnit+0x4c` differ.  Otherwise the implicit unit must have either a
    /// non-empty `CUnit+0x121` mask (`FUN_005b4bc0`) or a running Maelstrom
    /// timer (`FUN_005b6630`), and the target predicate
    /// `FUN_0059ca70(0x66, unit)` must accept the unit; that data-table
    /// predicate is supplied by the caller as `targetable`.
    pub fn a09_recharge_status_gate(&self, other: &SimUnit, targetable: bool) -> bool {
        self.owner == other.owner
            && (self.mask_121() != 0 || self.maelstrom_ticks() != 0)
            && targetable
    }

    /// `0x005cf1e5`: true when the unit's current byte facing is within five
    /// steps (of 256) of `wanted`.  `FUN_005692b0` computes the current byte
    /// facing from the unit's position; the result is folded into
    /// `0..=128` and compared with 6, so 0..=5 passes and 6..=128 fails.
    pub fn a09_facing_near(&self, wanted: u8) -> bool {
        let delta = wanted.wrapping_sub(self.facing) as u16;
        delta.min(0x100 - delta) < 6
    }
}

/// `0x005c8a54`: accumulator gate.  `FUN_006c1ee0` is called first for its
/// side effect; the routine then returns 0 while the force flag
/// `DAT_00fa3900` is clear and the accumulator `DAT_00fa38f8` is below
/// `0xfa` (250).  Once either condition holds it stores zero in
/// `DAT_00fa38fc` and tail-calls `FUN_0058b650`, i.e. it reports success and
/// restarts the accumulator.  Returns `(ready, next_counter_value)`.
pub fn a09_accumulator_gate(flag: bool, counter: u32) -> (bool, u32) {
    let ready = flag || counter >= 0xfa;
    (ready, if ready { 0 } else { counter })
}

/// `0x005c8cd0`: checked lookup of the value slot at node offset `0x14`.
/// Retail calls `FUN_00597430` with the key and aborts through `FUN_0093ec70`
/// when the lookup reports no node, so there is no default value; here a
/// miss is `None`.  `0x005c9350` stores a `u16` through this slot, which
/// fixes the value type.
pub fn a09_map_value_u16(map: &BTreeMap<i32, u16>, key: i32) -> Option<u16> {
    map.get(&key).copied()
}

/// `0x005c9350`: write a `u16` through the value slot returned by
/// [`a09_map_value_u16`] (`0x005c8cd0`).  Because the lookup aborts on a
/// missing key, this only updates an existing entry; `false` reports the
/// retail abort path and leaves the map unchanged.
pub fn a09_map_store_u16(map: &mut BTreeMap<i32, u16>, key: i32, value: u16) -> bool {
    match map.get_mut(&key) {
        Some(slot) => {
            *slot = value;
            true
        }
        None => false,
    }
}

/// `0x005c8ee0`: exact lookup in an ordered tree whose key is the unsigned
/// dword at node offset `0x10` and whose value is at `0x14`.  The walk is a
/// lower bound, and the caller keeps the node only when its key is also
/// `<= query`, so only an exact match is returned.  `keys` must be in
/// ascending order, as they are in the tree.
pub fn a09_unsigned_key_index(keys: &[u32], key: u32) -> Option<usize> {
    let index = keys.partition_point(|&k| k < key);
    (keys.get(index) == Some(&key)).then_some(index)
}

/// `0x005c8f20`: signed-key twin of [`a09_unsigned_key_index`].  The tree
/// walk and the final `key <= query` check are the same; only the key
/// comparisons are signed.  `keys` must be in ascending order.
pub fn a09_signed_key_index(keys: &[i32], key: i32) -> Option<usize> {
    let index = keys.partition_point(|&k| k < key);
    (keys.get(index) == Some(&key)).then_some(index)
}

#[cfg(test)]
mod tests_agent09 {
    use super::*;
    use crate::ids::unit as uid;
    use crate::sim::Order;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(crate::data::GameData::bundled().unwrap()),
            crate::map::Terrain::open(64, 64),
            2,
        )
    }

    #[test]
    fn value_gate_rejects_non_allied_buildings_and_flagged_units() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let cruiser = w.spawn(0, uid::BATTLECRUISER, 900, 320).unwrap();
        assert!(w.a09_value_target_gate(cruiser, true));
        assert!(!w.a09_value_target_gate(cruiser, false));

        let centre = w.spawn(0, uid::COMMAND_CENTER, 1400, 900).unwrap();
        assert!(!w.a09_value_target_gate(centre, true));

        assert!(!w.a09_value_target_gate(marine, true));
        w.units[marine].set_mask_123_bit(0);
        assert!(!w.a09_value_target_gate(marine, true));
        w.units[cruiser].set_mask_123_bit(0);
        assert!(!w.a09_value_target_gate(cruiser, true));
    }

    #[test]
    fn value_gate_lets_detectors_and_high_hp_units_through() {
        let mut w = world();
        let vessel = w.spawn(0, uid::SCIENCE_VESSEL, 320, 320).unwrap();
        w.units[vessel].hp = 10 << 8;
        assert!(w.data.unit(uid::SCIENCE_VESSEL).is_detector());
        assert!(w.a09_value_target_gate(vessel, true));

        let marine = w.spawn(0, uid::MARINE, 640, 640).unwrap();
        w.units[marine].hp = 10 << 8;
        assert!(!w.a09_value_target_gate(marine, true));
        w.units[marine].hp = 0x51 << 8;
        assert!(w.a09_value_target_gate(marine, true));
    }

    #[test]
    fn value_gate_uses_inclusive_81_point_threshold() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        w.units[marine].hp = 80 << 8;
        assert_eq!(w.unit_current_total_points(marine), 80);
        assert!(!w.a09_value_target_gate(marine, true));
        w.units[marine].hp = 81 << 8;
        assert_eq!(w.unit_current_total_points(marine), 81);
        assert!(w.a09_value_target_gate(marine, true));
    }

    #[test]
    fn energy_covers_heal_compares_whole_points() {
        let mut w = world();
        let ghost = w.spawn(0, uid::GHOST, 320, 320).unwrap();
        assert!(w.data.unit(uid::GHOST).has_energy());
        w.units[ghost].energy = 45;
        assert_eq!(w.unit_current_total_points(ghost), 45);
        assert!(w.a09_energy_covers_heal(ghost, true, false));

        w.units[ghost].energy = 44;
        assert!(!w.a09_energy_covers_heal(ghost, true, false));
    }

    #[test]
    fn energy_covers_heal_rejects_allied_flag_status_and_heroes() {
        let mut w = world();
        let ghost = w.spawn(0, uid::GHOST, 320, 320).unwrap();
        w.units[ghost].energy = 200;
        assert!(!w.a09_energy_covers_heal(ghost, false, false));
        assert!(!w.a09_energy_covers_heal(ghost, true, true));
        assert!(w.a09_energy_covers_heal(ghost, true, false));

        let hero = (0..w.data.units.len())
            .find(|&t| {
                let ty = w.data.unit(t as u16);
                ty.is_hero() && ty.has_energy()
            })
            .expect("bundled data has an energy hero") as u16;
        let hero = w.spawn(0, hero, 900, 900).unwrap();
        w.units[hero].energy = 250;
        assert!(!w.a09_energy_covers_heal(hero, true, false));
    }

    #[test]
    fn carrier_low_hp_target_requires_family_order_target_and_owner() {
        let mut w = world();
        let carrier = w.spawn(0, uid::CARRIER, 320, 320).unwrap();
        w.units[carrier].hp = 10 << 8;
        assert!(!w.a09_carrier_has_low_hp_target(carrier, 0));
        w.units[carrier].order = Order::AttackUnit { target: 7 };
        assert!(w.a09_carrier_has_low_hp_target(carrier, 0));

        assert!(!w.a09_carrier_has_low_hp_target(carrier, 1));
        w.units[carrier].hp = 11 << 8;
        assert!(!w.a09_carrier_has_low_hp_target(carrier, 0));

        let marine = w.spawn(0, uid::MARINE, 640, 640).unwrap();
        w.units[marine].hp = 5 << 8;
        w.units[marine].order = Order::AttackUnit { target: 7 };
        assert!(!w.a09_carrier_has_low_hp_target(marine, 0));
    }

    #[test]
    fn recharge_status_gate_needs_status_same_owner_and_target_predicate() {
        let mut w = world();
        let a = w.spawn(0, uid::MEDIC, 320, 320).unwrap();
        let b = w.spawn(0, uid::MARINE, 640, 640).unwrap();
        let mut ua = w.units[a].clone();
        let mut ub = w.units[b].clone();
        assert!(!ua.a09_recharge_status_gate(&ub, true));

        ua.set_mask_121_bit(0);
        assert!(ua.a09_recharge_status_gate(&ub, true));
        assert!(!ua.a09_recharge_status_gate(&ub, false));
        ub.owner = 1;
        assert!(!ua.a09_recharge_status_gate(&ub, true));

        let mut uc = w.units[a].clone();
        uc.clear_mask_121();
        uc.status.maelstrom_ticks = 3;
        assert!(uc.a09_recharge_status_gate(&w.units[b], true));
    }

    #[test]
    fn accumulator_gate_threshold_and_reset() {
        assert_eq!(a09_accumulator_gate(false, 0), (false, 0));
        assert_eq!(a09_accumulator_gate(false, 249), (false, 249));
        assert_eq!(a09_accumulator_gate(false, 250), (true, 0));
        assert_eq!(a09_accumulator_gate(true, 3), (true, 0));
    }

    #[test]
    fn map_slot_get_matches_existing_keys_only() {
        let mut map = BTreeMap::new();
        map.insert(7, 0x36e);
        assert_eq!(a09_map_value_u16(&map, 7), Some(0x36e));
        assert_eq!(a09_map_value_u16(&map, 8), None);
    }

    #[test]
    fn map_slot_store_only_overwrites_existing_entries() {
        let mut map = BTreeMap::new();
        map.insert(7, 0x36e);
        assert!(a09_map_store_u16(&mut map, 7, 0x36c));
        assert_eq!(map[&7], 0x36c);
        assert!(!a09_map_store_u16(&mut map, 9, 0x386));
        assert!(!map.contains_key(&9));
    }

    #[test]
    fn unsigned_tree_lookup_is_exact_match() {
        let keys = [1u32, 3, 5, 7];
        assert_eq!(a09_unsigned_key_index(&keys, 1), Some(0));
        assert_eq!(a09_unsigned_key_index(&keys, 5), Some(2));
        assert_eq!(a09_unsigned_key_index(&keys, 4), None);
        assert_eq!(a09_unsigned_key_index(&keys, 9), None);
        assert_eq!(a09_unsigned_key_index(&[], 1), None);
    }

    #[test]
    fn signed_tree_lookup_is_exact_match() {
        let keys = [-5i32, -1, 3];
        assert_eq!(a09_signed_key_index(&keys, -5), Some(0));
        assert_eq!(a09_signed_key_index(&keys, -1), Some(1));
        assert_eq!(a09_signed_key_index(&keys, 0), None);
        assert_eq!(a09_signed_key_index(&keys, 4), None);
    }

    #[test]
    fn facing_near_uses_five_step_window() {
        let mut w = world();
        let marine = w.spawn(0, uid::MARINE, 320, 320).unwrap();
        let mut u = w.units[marine].clone();
        u.facing = 250;
        assert!(u.a09_facing_near(250));
        assert!(u.a09_facing_near(254));
        assert!(u.a09_facing_near(255));
        assert!(!u.a09_facing_near(0));
        assert!(!u.a09_facing_near(1));

        u.facing = 0;
        assert!(u.a09_facing_near(5));
        assert!(!u.a09_facing_near(6));
        assert!(u.a09_facing_near(251));
        assert!(!u.a09_facing_near(250));
    }
}

// ===========================================================================
// Merged from src/translated/agent11.rs
// ===========================================================================
// Translation batch 11.  Only this file is edited by the batch.
//
// The batch covers the `decompiled_uncited` entries of the
// `0x005a0000..=0x005a3fff` range whose ledger size is at most 100 bytes.
// That window is retail unit-order/attack helper code; most of the ledger
// rows in it are not function entries (Ghidra split single routines at
// call sites and jump targets), so only rows that are real function starts
// are reconstructed here.
//
// The recovered semantics use the existing [`SimUnit`] order/target
// storage (`CUnit+0x5c`, `CUnit+0x64`), [`SimUnit::facing`] and the
// `units.dat`/`weapons.dat` columns exposed through
// [`crate::data::GameData`].  Two retail links are not modelled by the sim
// and are therefore passed in explicitly instead of stored: the
// `CUnit+0x70` subunit pointer and the `CUnit+0x4e` order-phase byte.

/// Byte direction from `(x1, y1)` towards `(x2, y2)` in the retail compass
/// convention: 0 = north, 64 = east, 128 = south, 192 = west.
///
/// The retail direction routine divides the deltas and feeds an integer
/// arctangent table; this uses the same convention via `atan2`, which can
/// differ from the table entry by one byte step.  The axis-exact cases are
/// reproduced exactly.
fn a11_direction_byte(dx: i32, dy: i32) -> u8 {
    if dx == 0 {
        return if dy < 1 { 0 } else { 0x80 };
    }
    let angle = (dx as f32).atan2(-(dy as f32));
    let mut a = (angle * 256.0 / std::f32::consts::TAU).round() as i32;
    a = (a + 256) % 256;
    a as u8
}

/// Retail octagonal distance estimate (the integer routine the attack
/// helpers use instead of a square root): `dx`/`dy` are absolute deltas.
///
/// The large axis and the small axis are ordered first; for diagonal
/// deltas the result is `large + small * 3 / 8` with the small correction
/// terms the retail routine applies.
fn a11_octagonal_distance(dx: i32, dy: i32) -> i32 {
    let mut large = dx.abs();
    let mut small = dy.abs();
    if large < small {
        std::mem::swap(&mut large, &mut small);
    }
    if large >> 2 < small {
        let adjusted = (small >> 1) + small;
        return (adjusted >> 2) + (((adjusted >> 7) - (large >> 6)) - (large >> 4)) + large;
    }
    large
}

impl World {
    /// `0x005a27d0`: pick the attack weapon for the current order target
    /// and report how many attack cues the attack-cue emission routine
    /// produces for it.
    ///
    /// The routine returns immediately when the order's unit-target slot
    /// (`CUnit+0x5c`) is empty.  `air` selects the retail air branch: the
    /// selector value 1 takes the ground weapon, and any other value
    /// (normally 2) takes the air weapon.  In the ground case an
    /// incomplete Lurker (`unit type 0x67` with `CUnit+0xdc` bit 4 clear)
    /// yields the `0x82` "no weapon" sentinel.  The selected weapon is cued
    /// once, and a second time when the `weapons.dat` damage-factor byte
    /// (exposed as [`crate::data::WeaponType::bullet_count`]) equals 2.
    ///
    /// Returns `None` when the unit has no order unit-target, otherwise
    /// `Some((weapon_id, cue_count))`.
    pub fn a11_attack_weapon_cues(&self, unit: &SimUnit, air: bool) -> Option<(u8, u8)> {
        unit.order_unit_target()?;
        let stats = self.data.unit(unit.type_id);
        let weapon = if air {
            stats.air_weapon
        } else if unit.type_id == uid::LURKER && !unit.completed {
            0x82
        } else {
            stats.ground_weapon
        };
        let cues = if self
            .data
            .weapon(weapon)
            .is_some_and(|w| w.bullet_count == 2)
        {
            2
        } else {
            1
        };
        Some((weapon, cues))
    }

    /// `0x005a2d90`: air weapon of the unit, falling back to the air weapon
    /// of its attached subunit.
    ///
    /// The routine reads the `units.dat` air weapon of the unit.  When that
    /// is the `0x82` sentinel it follows `CUnit+0x70`; a null link returns
    /// `0x82`, otherwise the air weapon of the linked unit is read.  The
    /// `CUnit+0x70` subunit pointer is not part of [`SimUnit`], so the
    /// linked unit is supplied by the caller.  (Ghidra split this routine
    /// into two ledger rows; the body after the split is part of the same
    /// method.)
    pub fn a11_air_weapon_with_subunit(&self, unit: &SimUnit, subunit: Option<&SimUnit>) -> u8 {
        let own = self.data.unit(unit.type_id).air_weapon;
        if own != 0x82 {
            return own;
        }
        match subunit {
            Some(link) => self.data.unit(link.type_id).air_weapon,
            None => 0x82,
        }
    }

    /// `0x005a3ed0`: minimum-range test used by the attack-target
    /// validation path.
    ///
    /// The effective target is the `CUnit+0x70` link when that link carries
    /// the `units.dat` subunit flag (`0x10`), otherwise the unit itself.
    /// The weapon is then selected exactly like `0x005a27d0`: the air weapon
    /// when the *source* unit is airborne (dynamic `CUnit+0xdc` bit 2),
    /// otherwise the ground weapon, with an incomplete Lurker collapsing to
    /// `0x82`.  A `0x82` weapon or a zero `weapons.dat` minimum range
    /// returns `false`; otherwise the routine reports whether the gap
    /// between the two unit rectangles is at most the weapon's minimum
    /// range.
    ///
    /// `target_subunit` stands in for the unmodelled `CUnit+0x70` link.
    pub fn a11_min_range_reached(
        &self,
        target: &SimUnit,
        target_subunit: Option<&SimUnit>,
        source: &SimUnit,
    ) -> bool {
        let effective = match target_subunit {
            Some(link) if self.data.unit(link.type_id).is_subunit() => link,
            _ => target,
        };
        let source_airborne = source.lifted || self.data.unit(source.type_id).is_flyer();
        let weapon = if source_airborne {
            self.data.unit(effective.type_id).air_weapon
        } else if effective.type_id == uid::LURKER && !effective.completed {
            0x82
        } else {
            self.data.unit(effective.type_id).ground_weapon
        };
        if weapon == 0x82 {
            return false;
        }
        let Some(stats) = self.data.weapon(weapon) else {
            return false;
        };
        if stats.min_range == 0 {
            return false;
        }
        let target_rect = self.a11_unit_rect(effective);
        let source_rect = self.a11_unit_rect(source);
        let gap_x = (target_rect.0 - source_rect.2)
            .max(source_rect.0 - target_rect.2)
            .max(0);
        let gap_y = (target_rect.1 - source_rect.3)
            .max(source_rect.1 - target_rect.3)
            .max(0);
        a11_octagonal_distance(gap_x, gap_y) <= stats.min_range as i32
    }

    /// Helper for `0x005a3ed0`: the `units.dat` rectangle of `unit` with
    /// the right/bottom edges advanced by one to the exclusive form the
    /// retail gap calculation uses.
    fn a11_unit_rect(&self, unit: &SimUnit) -> (i32, i32, i32, i32) {
        let (left, top, right, bottom) = self
            .data
            .unit(unit.type_id)
            .dimensions
            .rect_at((unit.x / fp(1), unit.y / fp(1)));
        (left, top, right + 1, bottom + 1)
    }
}

impl SimUnit {
    /// `0x005a31a0`: is the target inside the weapon's firing arc?
    ///
    /// The routine computes the direction byte from the unit's position to
    /// the target and, for a Lurker (`unit type 0x67`), writes that byte to
    /// `CUnit+0x21` and accepts immediately.  Every other unit measures the
    /// wrapped absolute difference between its facing (`CUnit+0x21`) and
    /// the direction, and compares it with the `weapons.dat` attack-angle
    /// byte (exposed as [`crate::data::WeaponType::attack_angle`]): the
    /// target is in the arc when `min(diff, 256 - diff) <= attack_angle`.
    ///
    /// `attack_angle` is passed in because the caller has the weapon row;
    /// only [`SimUnit::facing`] is written here.  `target` is in whole
    /// pixels, while [`SimUnit::x`]/[`SimUnit::y`] are 1/256-pixel fixed
    /// point and are converted first.
    pub fn a11_attack_angle_ok(&mut self, attack_angle: u8, target: (i32, i32)) -> bool {
        let dx = target.0 - self.x / fp(1);
        let dy = target.1 - self.y / fp(1);
        let angle = a11_direction_byte(dx, dy);
        if self.type_id == uid::LURKER {
            self.facing = angle;
            return true;
        }
        let diff = (i32::from(self.facing) - i32::from(angle)).rem_euclid(0x100);
        let delta = diff.min(0x100 - diff);
        delta <= i32::from(attack_angle)
    }

    /// `0x005a3150`: predicate used to finish/validate an order step.
    ///
    /// The routine returns true when the unit has no sprite
    /// (`CUnit+0x0c == 0`) or when its primary order id (`CUnit+0x4d`) is
    /// zero and its order-phase byte (`CUnit+0x4e`) is 1.  The sim maps the
    /// missing-sprite and zero-order cases onto [`SimUnit::alive`] and
    /// [`Order::Idle`] (the same mapping the already-translated
    /// sprite/order predicate uses); the order-phase byte is not stored, so
    /// the caller supplies it.
    pub fn a11_sprite_missing_or_order_phase(&self, order_phase: u8) -> bool {
        !self.alive || (matches!(self.order, Order::Idle) && order_phase == 1)
    }
}

#[cfg(test)]
mod tests_agent11 {
    use super::*;
    use crate::data::GameData;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn open_world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, type_id: u16, x: i32, y: i32) -> u32 {
        let i = world.spawn_px(0, type_id, x, y).unwrap();
        world.units[i].id
    }

    fn attach_target(world: &mut World, unit: u32, target: u32) {
        let i = world.index_of(unit).unwrap();
        world.units[i].order = Order::AttackUnit { target };
    }

    #[test]
    fn attack_weapon_cues_need_a_unit_target() {
        let mut w = open_world();
        let marine = spawn(&mut w, uid::MARINE, 640, 640);
        let enemy = spawn(&mut w, uid::MARINE, 700, 640);
        let i = w.index_of(marine).unwrap();
        assert_eq!(w.a11_attack_weapon_cues(&w.units[i], false), None);
        assert_eq!(w.a11_attack_weapon_cues(&w.units[i], true), None);

        attach_target(&mut w, marine, enemy);
        let (weapon, cues) = w.a11_attack_weapon_cues(&w.units[i], false).unwrap();
        assert_eq!(weapon, w.data.unit(uid::MARINE).ground_weapon);
        let expected_cues = if w.data.weapon(weapon).unwrap().bullet_count == 2 {
            2
        } else {
            1
        };
        assert_eq!(cues, expected_cues);
        assert!(w.units[i].order_unit_target().is_some());
    }

    #[test]
    fn attack_weapon_cues_select_ground_air_and_repeat_count() {
        let mut w = open_world();
        let marine = spawn(&mut w, uid::MARINE, 640, 640);
        let enemy = spawn(&mut w, uid::MARINE, 700, 640);
        let i = w.index_of(marine).unwrap();
        attach_target(&mut w, marine, enemy);

        let (ground, ground_cues) = w.a11_attack_weapon_cues(&w.units[i], false).unwrap();
        let (air, air_cues) = w.a11_attack_weapon_cues(&w.units[i], true).unwrap();
        assert_eq!(ground, w.data.unit(uid::MARINE).ground_weapon);
        assert_eq!(air, w.data.unit(uid::MARINE).air_weapon);
        let damage_factor = w.data.weapon(ground).unwrap().bullet_count;
        assert_eq!(ground_cues, if damage_factor == 2 { 2 } else { 1 });
        assert_eq!(
            air_cues,
            if w.data.weapon(air).unwrap().bullet_count == 2 {
                2
            } else {
                1
            }
        );

        // A weapon whose damage-factor byte is 2 is cued twice.  There is at
        // least one such ground weapon in the shipped table.
        let repeat_type = (0..w.data.units.len() as u16)
            .find(|&t| {
                w.data
                    .weapon(w.data.unit(t).ground_weapon)
                    .is_some_and(|s| s.bullet_count == 2)
            })
            .expect("a ground weapon with a damage factor of 2");
        let repeater = spawn(&mut w, repeat_type, 600, 600);
        attach_target(&mut w, repeater, enemy);
        let j = w.index_of(repeater).unwrap();
        assert_eq!(
            w.a11_attack_weapon_cues(&w.units[j], false),
            Some((w.data.unit(repeat_type).ground_weapon, 2))
        );
    }

    #[test]
    fn attack_weapon_cues_incomplete_lurker_has_no_weapon() {
        let mut w = open_world();
        let lurker = spawn(&mut w, uid::LURKER, 640, 640);
        let enemy = spawn(&mut w, uid::MARINE, 700, 640);
        let i = w.index_of(lurker).unwrap();
        attach_target(&mut w, lurker, enemy);
        w.units[i].completed = false;
        assert_eq!(
            w.a11_attack_weapon_cues(&w.units[i], false),
            Some((0x82, 1))
        );

        // The air selector bypasses the Lurker special case entirely, and the
        // Lurker row has the 0x82 air-weapon sentinel.
        assert_eq!(w.data.unit(uid::LURKER).air_weapon, 0x82);
        assert_eq!(w.a11_attack_weapon_cues(&w.units[i], true), Some((0x82, 1)));

        // A completed Lurker uses its ground weapon again.
        w.units[i].completed = true;
        assert_eq!(
            w.a11_attack_weapon_cues(&w.units[i], false),
            Some((w.data.unit(uid::LURKER).ground_weapon, 1))
        );
    }

    #[test]
    fn attack_angle_accepts_exact_facing_and_rejects_opposite() {
        let mut w = open_world();
        let marine = spawn(&mut w, uid::MARINE, 640, 640);
        let i = w.index_of(marine).unwrap();
        w.units[i].facing = 64; // east
        assert!(w.units[i].a11_attack_angle_ok(0, (740, 640)));
        // Due west is 128 byte steps away: 0x7f is outside, 0x80 is not.
        assert!(!w.units[i].a11_attack_angle_ok(0x7f, (540, 640)));
        assert!(w.units[i].a11_attack_angle_ok(0x80, (540, 640)));
        // A target slightly off the current facing is inside angle 0.
        w.units[i].facing = a11_direction_byte(100, 1);
        assert!(w.units[i].a11_attack_angle_ok(0, (740, 641)));
    }

    #[test]
    fn attack_angle_snaps_lurker_facing() {
        let mut w = open_world();
        let lurker = spawn(&mut w, uid::LURKER, 640, 640);
        let i = w.index_of(lurker).unwrap();
        w.units[i].facing = 0;
        assert!(w.units[i].a11_attack_angle_ok(0, (740, 640)));
        assert_eq!(w.units[i].facing, 64);
    }

    #[test]
    fn air_weapon_falls_back_to_the_subunit() {
        let mut w = open_world();
        let firebat = spawn(&mut w, uid::FIREBAT, 640, 640);
        let marine = spawn(&mut w, uid::MARINE, 660, 640);
        let i = w.index_of(firebat).unwrap();
        let j = w.index_of(marine).unwrap();
        assert_eq!(w.data.unit(uid::FIREBAT).air_weapon, 0x82);
        assert_eq!(
            w.a11_air_weapon_with_subunit(&w.units[i], Some(&w.units[j])),
            w.data.unit(uid::MARINE).air_weapon
        );
        assert_eq!(w.a11_air_weapon_with_subunit(&w.units[i], None), 0x82);
        // A unit with its own air weapon never consults the link.
        assert_ne!(w.data.unit(uid::MARINE).air_weapon, 0x82);
        assert_eq!(
            w.a11_air_weapon_with_subunit(&w.units[j], Some(&w.units[i])),
            w.data.unit(uid::MARINE).air_weapon
        );
    }

    #[test]
    fn min_range_reached_uses_rectangle_gap() {
        let mut w = open_world();
        let (target_type, min_range) = (0..w.data.units.len() as u16)
            .find_map(|t| {
                let stats = w.data.weapon(w.data.unit(t).ground_weapon)?;
                (stats.min_range > 0).then_some((t, stats.min_range))
            })
            .expect("a ground weapon with a minimum range");
        let target = spawn(&mut w, target_type, 640, 640);
        let source = spawn(&mut w, uid::MARINE, 646, 640);
        let ti = w.index_of(target).unwrap();
        let si = w.index_of(source).unwrap();
        w.units[ti].completed = true;
        assert!(w.a11_min_range_reached(&w.units[ti], None, &w.units[si]));

        // Push the source beyond the minimum range plus both boxes.
        let far = min_range as i32 + 200;
        w.units[si].x = w.units[ti].x + far * fp(1);
        assert!(!w.a11_min_range_reached(&w.units[ti], None, &w.units[si]));
    }

    #[test]
    fn min_range_reached_ignores_no_weapon_and_zero_min_range() {
        let mut w = open_world();
        let source = spawn(&mut w, uid::MARINE, 646, 640);
        let si = w.index_of(source).unwrap();

        let unarmed_type = (0..w.data.units.len() as u16)
            .find(|&t| w.data.unit(t).ground_weapon == 0x82)
            .expect("a unit type without a ground weapon");
        let unarmed = spawn(&mut w, unarmed_type, 640, 640);
        let ui = w.index_of(unarmed).unwrap();
        assert!(!w.a11_min_range_reached(&w.units[ui], None, &w.units[si]));

        let zero_type = (0..w.data.units.len() as u16)
            .find(|&t| {
                w.data
                    .weapon(w.data.unit(t).ground_weapon)
                    .is_some_and(|s| s.min_range == 0 && s.max_range > 0)
            })
            .expect("a ground weapon with zero minimum range");
        let zero = spawn(&mut w, zero_type, 800, 800);
        let zi = w.index_of(zero).unwrap();
        w.units[zi].completed = true;
        assert!(!w.a11_min_range_reached(&w.units[zi], None, &w.units[si]));
    }

    #[test]
    fn min_range_reached_prefers_a_subunit_target() {
        let mut w = open_world();
        // A marine's ground weapon has no minimum range.
        let target = spawn(&mut w, uid::MARINE, 640, 640);
        let source = spawn(&mut w, uid::MARINE, 646, 640);
        let ti = w.index_of(target).unwrap();
        let si = w.index_of(source).unwrap();
        assert!(!w.a11_min_range_reached(&w.units[ti], None, &w.units[si]));

        // A `units.dat` subunit row with a minimum-range ground weapon.
        let subunit_type = (0..w.data.units.len() as u16)
            .find(|&t| {
                w.data.unit(t).is_subunit()
                    && w.data
                        .weapon(w.data.unit(t).ground_weapon)
                        .is_some_and(|s| s.min_range > 0)
            })
            .expect("a subunit with a minimum-range ground weapon");
        let subunit = spawn(&mut w, subunit_type, 660, 640);
        let ci = w.index_of(subunit).unwrap();
        assert!(w.a11_min_range_reached(&w.units[ti], Some(&w.units[ci]), &w.units[si]));
        // A non-subunit link is ignored, leaving the marine's zero min range.
        let plain = spawn(&mut w, uid::FIREBAT, 620, 640);
        let fi = w.index_of(plain).unwrap();
        assert!(!w.a11_min_range_reached(&w.units[ti], Some(&w.units[fi]), &w.units[si]));
    }

    #[test]
    fn sprite_missing_or_order_phase_predicate() {
        let mut w = open_world();
        let marine = spawn(&mut w, uid::MARINE, 640, 640);
        let i = w.index_of(marine).unwrap();
        assert!(matches!(w.units[i].order, Order::Idle));
        assert!(w.units[i].a11_sprite_missing_or_order_phase(1));
        assert!(!w.units[i].a11_sprite_missing_or_order_phase(0));
        assert!(!w.units[i].a11_sprite_missing_or_order_phase(2));

        w.units[i].order = Order::Move { pos: (700, 700) };
        assert!(!w.units[i].a11_sprite_missing_or_order_phase(1));

        // No sprite is modelled as a dead unit; then the phase is irrelevant.
        w.units[i].alive = false;
        assert!(w.units[i].a11_sprite_missing_or_order_phase(0));
        assert!(w.units[i].a11_sprite_missing_or_order_phase(2));
    }
}

// ===========================================================================
// Merged from src/translated/agent12.rs
// ===========================================================================
// Translation batch 12.  Only this file is edited by the batch.
//
// The routines reconstructed here are the retail unit-search helpers that
// live in `0x005a4000..=0x005a7fff`.  Retail keeps a temporary "search
// grid" of per-column and per-row unit lists (`CUnit+0x13c..+0x148` are the
// unit's tile bounds), plus a scratch mark array and a small stack of saved
// result cursors.  [`crate::sim::World`] already exposes the unit records,
// their `units.dat` boxes and the terrain dimensions, so every query below
// is answered directly from [`World::units`]; nothing here adds persistent
// state.  The routines that only shuffled the retail scratch buffers are
// translated as free helpers that operate on caller-owned slices/vectors.

/// Retail stores unit positions in 1/256-pixel units.
const A12_FP: i32 = 256;

impl World {
    /// `0x005a4a70` (4-byte entry) / `0x005a4a74` (body): target switch gate.
    ///
    /// The routine takes the prospective target and the player's current target
    /// and returns 1 when the current target may be replaced.  It is a no when
    /// both pointers are the same and when the new unit is not hostile.  When a
    /// current target exists, is alive and can still be attacked, the switch is
    /// allowed only if the new unit is visible while the old one is not; this is
    /// the "keep shooting what you can see" rule of the auto-acquire path.
    ///
    /// Visibility is read from the cached per-player `CUnit+0xe4` mask
    /// ([`SimUnit::visibility_mask`]); attackability mirrors the retail guards
    /// (no lockdown/stasis/maelstrom lock, no disabled capability bit, not
    /// loaded into a transport or Bunker).
    pub fn a12_may_switch_target(&self, owner: u8, current: Option<u32>, candidate: u32) -> bool {
        if current == Some(candidate) {
            return false;
        }
        let Some(candidate_idx) = self.index_of(candidate) else {
            return false;
        };
        let new = &self.units[candidate_idx];
        if !new.alive || !self.is_enemy(owner, new.owner) {
            return false;
        }
        if let Some(old_id) = current
            && let Some(old_idx) = self.index_of(old_id)
        {
            let old = &self.units[old_idx];
            if old.alive && self.is_enemy(owner, old.owner) && a12_attackable(old) {
                let bit = 1u32 << (owner & 31);
                return new.visibility_mask & bit != 0 && old.visibility_mask & bit == 0;
            }
        }
        true
    }
}

/// `0x005a4b90`: resizes one of the retail unit-search buffers to
/// `param + 1` entries.  The routine is the inlined `std::vector<CUnit*>`
/// `resize`: the shrink half erases the tail, the growth half appends
/// null pointers.  The translated helper performs the equivalent
/// [`Vec::resize`] with the same null (zero) fill value.
pub fn a12_resize_search_buffer(buffer: &mut Vec<u32>, depth: usize) {
    buffer.resize(depth + 1, 0);
}

/// `0x005a5000`: clears the search scratch array and resets the result
/// cursor.  Retail zero-fills the scratch mark array and writes zero to the
/// result count.  The caller owns the mark array in this model, so only the
/// fill is reproduced; the reset count is `0`.
pub fn a12_clear_search_marks(marks: &mut [u32]) {
    marks.fill(0);
}

impl World {
    /// `0x005a5210`: units in the tile ring around a unit's box.
    ///
    /// Starting from `index`'s tile bounds (`CUnit+0x13c..+0x148`), retail scans
    /// the grid columns to the right, then to the left, then the rows below and
    /// above.  Each of the four scans is grown by `dx`/`dy` tiles and collects a
    /// unit when its perpendicular span overlaps the grown band and it is not
    /// the caller itself.  The returned ids follow that scan order (right, left,
    /// down, up) with a unit emitted once even when two side scans both match a
    /// diagonal neighbour.
    pub fn a12_units_around_box(&self, index: usize, dx: i32, dy: i32) -> Vec<u32> {
        let Some(origin) = self.units.get(index) else {
            return Vec::new();
        };
        let (left, top, right, bottom) = a12_tile_bounds(self, origin);
        let (left_edge, right_edge) = (left - dx, right + dx);
        let (top_edge, bottom_edge) = (top - dy, bottom + dy);

        let mut result = Vec::new();
        let push = |unit: &SimUnit, result: &mut Vec<u32>| {
            if !result.contains(&unit.id) {
                result.push(unit.id);
            }
        };
        for unit in &self.units {
            if !unit.alive || unit.id == origin.id {
                continue;
            }
            let (l, t, _, b) = a12_tile_bounds(self, unit);
            // Columns to the right of the origin box.
            if l > right && l <= right_edge && t <= bottom_edge && b >= top_edge {
                push(unit, &mut result);
            }
        }
        for unit in &self.units {
            if !unit.alive || unit.id == origin.id {
                continue;
            }
            let (_, t, r, b) = a12_tile_bounds(self, unit);
            // Columns to the left of the origin box.
            if r < left && r >= left_edge && t <= bottom_edge && b >= top_edge {
                push(unit, &mut result);
            }
        }
        for unit in &self.units {
            if !unit.alive || unit.id == origin.id {
                continue;
            }
            let (l, t, r, _) = a12_tile_bounds(self, unit);
            // Rows below the origin box.
            if t > bottom && t <= bottom_edge && l <= right_edge && r >= left_edge {
                push(unit, &mut result);
            }
        }
        for unit in &self.units {
            if !unit.alive || unit.id == origin.id {
                continue;
            }
            let (l, _, r, b) = a12_tile_bounds(self, unit);
            // Rows above the origin box.
            if b < top && b >= top_edge && l <= right_edge && r >= left_edge {
                push(unit, &mut result);
            }
        }
        result
    }

    /// `0x005a55b2`: collects units while walking grid rows downward.
    ///
    /// The routine starts at `start_row` and steps towards smaller row indices
    /// while the row edge coordinate stays at or above `row_limit`.  Every unit
    /// in each visited row is kept when its tile box horizontally overlaps the
    /// inclusive-to-exclusive tile range `[min_x, max_x)`, which is the same
    /// overlap test the retail row lists use.  A unit that spans several
    /// visited rows would be reached once per row in retail; the translated
    /// helper keeps only its first occurrence.
    pub fn a12_units_in_row_band(
        &self,
        start_row: i32,
        row_limit: i32,
        min_x: i32,
        max_x: i32,
    ) -> Vec<u32> {
        if start_row < row_limit {
            return Vec::new();
        }
        let mut result = Vec::new();
        for row in (row_limit..=start_row).rev() {
            for unit in &self.units {
                if !unit.alive {
                    continue;
                }
                let (l, t, r, b) = a12_tile_bounds(self, unit);
                if t <= row && b >= row && r >= min_x && l < max_x && !result.contains(&unit.id) {
                    result.push(unit.id);
                }
            }
        }
        result
    }

    /// `0x005a574f`: units whose tile box contains the given tile.
    ///
    /// The retail routine walks the column's unit list, keeps the units whose
    /// column span covers `tile_x`, and verifies the row span against `tile_y`
    /// before appending them to the result buffer.  The translated query scans
    /// every live unit in spawn order.
    pub fn a12_units_at_tile(&self, tile_x: i32, tile_y: i32) -> Vec<u32> {
        self.units
            .iter()
            .filter(|unit| {
                if !unit.alive {
                    return false;
                }
                let (l, t, r, b) = a12_tile_bounds(self, unit);
                l <= tile_x && tile_x <= r && t <= tile_y && tile_y <= b
            })
            .map(|unit| unit.id)
            .collect()
    }
}

/// `0x005a5770`: pops one saved search cursor.
///
/// Retail decrements the saved-depth counter and restores the result cursor
/// from the depth stack.  The helper reports the popped cursor (`None` when
/// the stack is already empty) and updates the caller's depth, so no
/// persistent global is needed.
pub fn a12_pop_search_cursor(stack: &[u32], depth: &mut usize) -> Option<u32> {
    if *depth == 0 {
        return None;
    }
    *depth -= 1;
    Some(stack.get(*depth).copied().unwrap_or(0))
}

impl World {
    /// `0x005a5790`: removes matching units from a search result list.
    ///
    /// The retail routine walks the result list, asks the per-unit getter for
    /// its short record id and compacts the list when that id equals the
    /// selector passed in.  In this model the per-unit row is
    /// [`SimUnit::type_id`], so the helper filters that row out of a caller-owned
    /// result list while preserving the order of the survivors.  Unknown ids are
    /// left untouched, matching the retail pointer-list behaviour.
    pub fn a12_remove_units_of_type(&self, ids: &mut Vec<u32>, type_id: u16) {
        ids.retain(|id| self.unit(*id).is_none_or(|unit| unit.type_id != type_id));
    }

    /// `0x005a5990`: units intersecting a tile rectangle.
    ///
    /// Retail intersects the column list of every column in `left..=right` with
    /// the row list of every row in `top..=bottom`.  A unit is therefore kept
    /// when both its tile column span and its tile row span intersect the
    /// inclusive rectangle.  Iterating the unit array directly yields one entry
    /// per unit; results are ordered column-major, then by row, which is the
    /// order the column lists are walked.
    pub fn a12_units_in_tile_rect(&self, left: i32, top: i32, right: i32, bottom: i32) -> Vec<u32> {
        let mut hits: Vec<(i32, i32, usize, u32)> = self
            .units
            .iter()
            .enumerate()
            .filter(|(_, unit)| unit.alive)
            .filter_map(|(slot, unit)| {
                let (l, t, r, b) = a12_tile_bounds(self, unit);
                (l <= right && r >= left && t <= bottom && b >= top)
                    .then_some((l, t, slot, unit.id))
            })
            .collect();
        hits.sort_by_key(|&(l, t, slot, _)| (l, t, slot));
        hits.into_iter().map(|(_, _, _, id)| id).collect()
    }

    /// `0x005a5fb0`: map-margin guard for a tile row and pixel column.
    ///
    /// The retail check divides the 16-bit `AX` pixel coordinate by 32 to get a
    /// tile column and aborts when either `y + 2` reaches the map height or
    /// `x / 32 + 2` reaches the map width.  The translated predicate returns
    /// true when both coordinates stay inside that two-tile margin, which is the
    /// success path of the original routine.
    pub fn a12_tile_margin_ok(&self, x_px: i32, y_tile: i32) -> bool {
        let ax = i32::from(x_px as i16);
        let tile_x = (((ax >> 31) & 0x1f) + ax) >> 5;
        y_tile + 2 < self.terrain.height as i32 && tile_x + 2 < self.terrain.width as i32
    }
}

/// Retail attackability guards in front of target acquisition (the
/// `CUnit+0xdc` capability bit, the lock status timers and the hidden-sprite
/// states).  A unit that fails any guard cannot be retained as a target.
fn a12_attackable(unit: &SimUnit) -> bool {
    unit.alive
        && !unit.flag_26
        && unit.in_transport.is_none()
        && !unit.in_bunker
        && unit.status.lockdown_ticks == 0
        && unit.status.stasis_ticks == 0
        && unit.status.maelstrom_ticks == 0
}

/// Retail per-unit tile bounds (`CUnit+0x13c`, `+0x140`, `+0x144`, `+0x148`)
/// rebuilt from the `units.dat` box around the fixed-point centre.
fn a12_tile_bounds(world: &World, unit: &SimUnit) -> (i32, i32, i32, i32) {
    let dims = &world.data.unit(unit.type_id).dimensions;
    let px = unit.x.div_euclid(A12_FP);
    let py = unit.y.div_euclid(A12_FP);
    (
        (px - i32::from(dims.left)) >> 5,
        (py - i32::from(dims.top)) >> 5,
        (px + i32::from(dims.right)) >> 5,
        (py + i32::from(dims.bottom)) >> 5,
    )
}

#[cfg(test)]
mod tests_agent12 {
    use super::*;
    use crate::data::GameData;
    use crate::ids::unit as uid;
    use crate::map::Terrain;
    use std::sync::Arc;

    fn world() -> World {
        World::new(
            Arc::new(GameData::bundled().unwrap()),
            Terrain::open(64, 64),
            2,
        )
    }

    fn spawn(world: &mut World, owner: usize, type_id: u16, x: i32, y: i32) -> u32 {
        let slot = world.spawn(owner, type_id, x, y).expect("spawn");
        world.units[slot].id
    }

    fn slot_of(world: &World, id: u32) -> usize {
        world.index_of(id).expect("unit present")
    }

    #[test]
    fn switch_target_rejects_same_ally_and_dead_candidates() {
        let mut w = world();
        let viewer = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let enemy = spawn(&mut w, 1, uid::MARINE, 640, 320);
        let friend = spawn(&mut w, 0, uid::MARINE, 960, 320);

        assert!(!w.a12_may_switch_target(0, Some(enemy), enemy));
        assert!(!w.a12_may_switch_target(0, Some(viewer), friend));
        assert!(!w.a12_may_switch_target(0, Some(viewer), 0xdead_beef));
        // Undiscovered candidate: no current target means acquiring is fine.
        assert!(w.a12_may_switch_target(0, Some(viewer), enemy));

        let enemy_idx = slot_of(&w, enemy);
        w.units[enemy_idx].alive = false;
        assert!(!w.a12_may_switch_target(0, Some(viewer), enemy));
    }

    #[test]
    fn switch_prefers_only_a_visible_replacement_for_a_hidden_target() {
        let mut w = world();
        let old = spawn(&mut w, 1, uid::MARINE, 640, 320);
        let new = spawn(&mut w, 1, uid::MARINE, 640, 640);
        let old_idx = slot_of(&w, old);
        let new_idx = slot_of(&w, new);

        let bit = 1u32;
        w.units[new_idx].visibility_mask = u32::MAX;
        w.units[old_idx].visibility_mask = u32::MAX;
        assert!(!w.a12_may_switch_target(0, Some(old), new));

        w.units[old_idx].visibility_mask &= !bit;
        assert!(w.a12_may_switch_target(0, Some(old), new));

        w.units[new_idx].visibility_mask &= !bit;
        assert!(!w.a12_may_switch_target(0, Some(old), new));

        // A locked old target cannot be retained, so the gate opens.
        w.units[old_idx].visibility_mask = u32::MAX;
        w.units[new_idx].visibility_mask = u32::MAX;
        w.units[old_idx].status.lockdown_ticks = 10;
        assert!(w.a12_may_switch_target(0, Some(old), new));
        w.units[old_idx].status.lockdown_ticks = 0;
        assert!(!w.a12_may_switch_target(0, Some(old), new));
    }

    #[test]
    fn search_buffer_resize_matches_vector_resize() {
        let mut buffer = vec![7, 8, 9];
        a12_resize_search_buffer(&mut buffer, 1);
        assert_eq!(buffer, vec![7, 8]);
        a12_resize_search_buffer(&mut buffer, 4);
        assert_eq!(buffer, vec![7, 8, 0, 0, 0]);
    }

    #[test]
    fn clearing_the_search_marks_zeros_the_scratch_array() {
        let mut marks = [1u32, 2, 3, 4];
        a12_clear_search_marks(&mut marks);
        assert_eq!(marks, [0; 4]);
    }

    #[test]
    fn around_box_finds_adjacent_units_and_skips_overlapping_ones() {
        let mut w = world();
        let self_id = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let same = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let right = spawn(&mut w, 1, uid::MARINE, 448, 320);
        let below = spawn(&mut w, 1, uid::MARINE, 320, 448);
        let far = spawn(&mut w, 1, uid::MARINE, 992, 992);
        let self_idx = slot_of(&w, self_id);

        let near = w.a12_units_around_box(self_idx, 4, 4);
        assert!(near.contains(&right), "right neighbour: {near:?}");
        assert!(near.contains(&below), "lower neighbour: {near:?}");
        assert!(!near.contains(&self_id), "origin must be excluded");
        assert!(!near.contains(&same), "overlapping unit is not in the ring");
        assert!(!near.contains(&far), "far unit must be excluded: {near:?}");

        let narrow = w.a12_units_around_box(self_idx, 2, 2);
        assert!(
            !narrow.contains(&right),
            "2-tile margin is too small: {narrow:?}"
        );
        assert!(
            !narrow.contains(&below),
            "2-tile margin is too small: {narrow:?}"
        );
    }

    #[test]
    fn row_band_walks_downward_and_tests_horizontal_overlap() {
        let mut w = world();
        let top = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let bottom = spawn(&mut w, 1, uid::MARINE, 320, 448);
        let side = spawn(&mut w, 1, uid::MARINE, 700, 448);

        let (_, top_t, _, _) = a12_tile_bounds(&w, &w.units[slot_of(&w, top)]);
        let (_, _, _, bottom_b) = a12_tile_bounds(&w, &w.units[slot_of(&w, bottom)]);
        let band = w.a12_units_in_row_band(bottom_b, top_t, 0, 16);
        assert!(band.contains(&top), "top unit: {band:?}");
        assert!(band.contains(&bottom), "bottom unit: {band:?}");
        assert!(!band.contains(&side), "unit outside the x band: {band:?}");

        let empty = w.a12_units_in_row_band(top_t - 1, bottom_b + 1, 0, 16);
        assert!(empty.is_empty(), "inverted range must be empty");
    }

    #[test]
    fn units_at_tile_uses_the_units_dat_box() {
        let mut w = world();
        let here = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let far = spawn(&mut w, 1, uid::MARINE, 992, 992);

        let at = w.a12_units_at_tile(10, 10);
        assert!(at.contains(&here), "unit at tile 10,10: {at:?}");
        assert!(!at.contains(&far));
        assert!(w.a12_units_at_tile(31, 31).iter().all(|id| *id != here));
        assert!(w.a12_units_at_tile(31, 31).contains(&far));
    }

    #[test]
    fn search_cursor_pop_reports_and_restores_saved_depth() {
        let stack = [11u32, 22, 33];
        let mut depth = 3;
        assert_eq!(a12_pop_search_cursor(&stack, &mut depth), Some(33));
        assert_eq!(depth, 2);
        assert_eq!(a12_pop_search_cursor(&stack, &mut depth), Some(22));
        assert_eq!(depth, 1);
        assert_eq!(a12_pop_search_cursor(&stack, &mut depth), Some(11));
        assert_eq!(depth, 0);
        assert_eq!(a12_pop_search_cursor(&stack, &mut depth), None);
        assert_eq!(depth, 0);
    }

    #[test]
    fn result_list_filter_removes_only_the_requested_type() {
        let mut w = world();
        let marine = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let zealot = spawn(&mut w, 0, uid::ZEALOT, 640, 640);
        let mut ids = vec![marine, zealot, 0xdead_beef];
        w.a12_remove_units_of_type(&mut ids, uid::MARINE);
        assert_eq!(ids, vec![zealot, 0xdead_beef]);

        w.a12_remove_units_of_type(&mut ids, uid::ZEALOT);
        assert_eq!(ids, vec![0xdead_beef]);
    }

    #[test]
    fn tile_rect_query_returns_column_major_intersections() {
        let mut w = world();
        let inside = spawn(&mut w, 0, uid::MARINE, 320, 320);
        let lower = spawn(&mut w, 1, uid::MARINE, 320, 448);
        let outside = spawn(&mut w, 1, uid::MARINE, 992, 992);

        let hits = w.a12_units_in_tile_rect(9, 9, 11, 11);
        assert!(hits.contains(&inside), "inside rectangle: {hits:?}");
        assert!(!hits.contains(&lower), "row is outside the rectangle");
        assert!(!hits.contains(&outside), "far unit is outside");

        let both = w.a12_units_in_tile_rect(9, 9, 14, 14);
        assert!(both.contains(&inside));
        assert!(both.contains(&lower));
        assert!(!both.contains(&outside));
        assert_eq!(both.len(), 2);
    }

    #[test]
    fn tile_margin_guard_requires_both_coordinates_inside() {
        let w = world();
        assert!(w.a12_tile_margin_ok(0, 0));
        assert!(w.a12_tile_margin_ok(61 * 32, 61));
        assert!(!w.a12_tile_margin_ok(62 * 32, 0));
        assert!(!w.a12_tile_margin_ok(0, 62));
        assert!(!w.a12_tile_margin_ok(62 * 32, 62));
    }
}

