        assert!(w13a04_owner_has_flag_20(3, 3, 0x20));
        assert!(!w13a04_owner_has_flag_20(3, 3, 0x08));
        assert!(!w13a04_owner_has_flag_20(4, 3, 0x20));
        assert!(w13a04_owner_has_flag_08(3, 3, 0x08));
