        assert!(!w15a08_cell_flags_match(&g, 4, 40, 40, 1, 2));
        assert!(!w15a08_cell_flags_match(&g, 4, 0, 0, 1, 0));
        assert!(!w15a08_cell_flags_match(&g, 4, -40, 0, 1, 0));
        assert!(!w15a08_cell_flags_match(&g, 4, 4000, 4000, 1, 0));
