        assert_eq!(w15a08_call_with_minus_one(5, |a, b| (a, b)), (u32::MAX, 5));
        let mut failed = None;
        assert!(!w15a08_try_slot(1, 2, |_| false, |s| failed = Some(s)));
        assert_eq!(failed, Some((1 + 24) * 4 + 0x58_a364));
        assert!(w15a08_try_slot(1, 2, |_| true, |_| panic!()));
