        let l = [5u32, 6, 7, 0, 9];
        assert_eq!(w15a08_find_first(&l, None), 5);
        assert_eq!(w15a08_find_first(&l, Some(&|e| e == 7)), 7);
        assert_eq!(w15a08_find_first(&l, Some(&|e| e == 9)), 0);
        assert_eq!(w15a08_find_first(&[], None), 0);
